175	static uint64_t monotonic_us(void)
176	{
177	  struct timespec now;
178	
179	  if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
180	    {
181	      return 0;
182	    }
183	
184	  return (uint64_t)now.tv_sec * 1000000 + now.tv_nsec / 1000;
185	}
186	
187	static void perf_record(uint64_t now, uint64_t *first, uint64_t *last,
188	                        uint32_t *count, uint32_t *max_gap)
189	{
190	  if (now == 0)
191	    {
192	      return;
193	    }
194	
195	  if (*count == 0)
196	    {
197	      *first = now;
198	    }
199	  else
200	    {
201	      uint64_t gap = now - *last;
202	
203	      if (gap > *max_gap)
204	        {
205	          *max_gap = gap > UINT32_MAX ? UINT32_MAX : (uint32_t)gap;
206	        }
207	    }
208	
209	  *last = now;
210	  (*count)++;
211	}
212	
213	static uint32_t perf_rate_x10(uint32_t count, uint64_t first, uint64_t last)
214	{
215	  uint64_t elapsed;
216	
217	  if (count < 2 || last <= first)
218	    {
219	      return 0;
220	    }
221	
222	  elapsed = last - first;
223	  return (uint32_t)((uint64_t)(count - 1) * 10000000 / elapsed);
224	}
225	
226	static void perf_print(void)
227	{
228	  uint32_t input_rate = perf_rate_x10(g_app.perf.input_events,
229	                                      g_app.perf.first_input_us,
230	                                      g_app.perf.last_input_us);
231	  uint32_t frame_rate = perf_rate_x10(g_app.perf.frame_events,
232	                                      g_app.perf.first_frame_us,
233	                                      g_app.perf.last_frame_us);
234	
235	  if (g_app.perf.input_events < 2)
236	    {
237	      return;
238	    }
239	
240	  printf("VELARIDE_PERF: input=%" PRIu32 ".%" PRIu32
241	         "Hz max_gap=%" PRIu32 "ms refresh=%" PRIu32 ".%" PRIu32
242	         "Hz max_gap=%" PRIu32 "ms samples=%" PRIu32 "/%" PRIu32 "\n",
243	         input_rate / 10, input_rate % 10,
244	         g_app.perf.max_input_gap_us / 1000,
245	         frame_rate / 10, frame_rate % 10,
246	         g_app.perf.max_frame_gap_us / 1000,
247	         g_app.perf.input_events, g_app.perf.frame_events);
248	}
