279	/****************************************************************************
280	 * Name: make_label
281	 *
282	 * Description:
283	 *   建一个标签的公共套路：设文本、颜色、字体，挂到父对象上。
284	 *
285	 * Input Parameters:
286	 *   parent - 父对象
287	 *   text   - 初始文本
288	 *   color  - 文字颜色
289	 *   font   - 字体，NULL 表示用继承的默认字体
290	 *
291	 * Returned Value:
292	 *   新建的标签对象。
293	 *
294	 ****************************************************************************/
295	
296	static lv_obj_t *make_label(lv_obj_t *parent, const char *text,
297	                            lv_color_t color, const lv_font_t *font)
298	{
299	  lv_obj_t *label = lv_label_create(parent);
300	
301	  lv_label_set_text(label, text);
302	  lv_obj_set_style_text_color(label, color, LV_PART_MAIN);
303	
304	  if (font != NULL)
305	    {
306	      lv_obj_set_style_text_font(label, font, LV_PART_MAIN);
307	    }
308	
309	  return label;
310	}
