312	/****************************************************************************
313	 * Name: make_card
314	 *
315	 * Description:
316	 *   建一张整屏卡片。卡片本身不可滚动（滚动交给父容器），
317	 *   内部用竖向 flex 居中排布。
318	 *
319	 * Input Parameters:
320	 *   parent - 滚动容器
321	 *   bg     - 卡片背景色
322	 *
323	 * Returned Value:
324	 *   新建的卡片对象。
325	 *
326	 ****************************************************************************/
327	
328	static lv_obj_t *make_card(lv_obj_t *parent, lv_color_t bg)
329	{
330	  lv_obj_t *card = lv_obj_create(parent);
331	
332	  lv_obj_set_size(card, SCR_W, SCR_H);
333	  lv_obj_set_style_bg_color(card, bg, LV_PART_MAIN);
334	  lv_obj_set_style_bg_opa(card, LV_OPA_COVER, LV_PART_MAIN);
335	  lv_obj_set_style_border_width(card, 0, LV_PART_MAIN);
336	  lv_obj_set_style_radius(card, 0, LV_PART_MAIN);
337	  lv_obj_set_style_pad_all(card, 24, LV_PART_MAIN);
338	
339	  /* Match the official watch_v9 icon input flags.  The card is the stable
340	   * touch target and bubbles pointer events to the page-level gesture
341	   * handler.  Without EVENT_BUBBLE the page callback never receives
342	   * PRESSED/PRESSING/RELEASED when a child covers the screen.
343	   */
344	
345	  lv_obj_remove_flag(card, LV_OBJ_FLAG_SCROLLABLE);
346	  lv_obj_add_flag(card, LV_OBJ_FLAG_CLICKABLE |
347	                        LV_OBJ_FLAG_EVENT_BUBBLE |
348	                        LV_OBJ_FLAG_PRESS_LOCK);
349	
350	  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
351	  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_CENTER,
352	                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
353	
354	  return card;
355	}
