357	/****************************************************************************
358	 * Name: make_stat_row
359	 *
360	 * Description:
361	 *   建一行横排的数据格子（数值在上、单位在下）。
362	 *   返回的数组按传入顺序填好数值标签，调用方拿去刷新。
363	 *
364	 * Input Parameters:
365	 *   parent  - 父对象
366	 *   labels  - 单位文字数组
367	 *   out     - 输出：每个格子的数值标签
368	 *   count   - 格子数量
369	 *
370	 ****************************************************************************/
371	
372	static void make_stat_row(lv_obj_t *parent, const char * const *labels,
373	                          lv_obj_t **out, int count)
374	{
375	  lv_obj_t *row = lv_obj_create(parent);
376	  int i;
377	
378	  lv_obj_remove_style_all(row);
379	  lv_obj_set_size(row, LV_PCT(100), LV_SIZE_CONTENT);
380	  lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
381	  lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
382	  lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_EVENLY,
383	                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
384	
385	  for (i = 0; i < count; i++)
386	    {
387	      lv_obj_t *cell = lv_obj_create(row);
388	
389	      lv_obj_remove_style_all(cell);
390	      lv_obj_set_size(cell, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
391	      lv_obj_remove_flag(cell, LV_OBJ_FLAG_SCROLLABLE |
392	                               LV_OBJ_FLAG_CLICKABLE);
393	      lv_obj_set_flex_flow(cell, LV_FLEX_FLOW_COLUMN);
394	      lv_obj_set_flex_align(cell, LV_FLEX_ALIGN_CENTER,
395	                            LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
396	
397	      out[i] = make_label(cell, "0", COLOR_WHITE, &lv_font_montserrat_24);
398	      make_label(cell, labels[i], COLOR_MUTED, NULL);
399	    }
400	}
