527	/****************************************************************************
528	 * Name: refr_start_cb
529	 *
530	 * Description:
531	 *   渲染开始时应用累加的滚动位移。这是跟手手感的关键。
532	 *
533	 *   LVGL 默认滚动是"触摸事件一到就滚"，滚动时机和渲染时机不同步，
534	 *   帧间隔会抖（实测 8ms~120ms）。官方 watch_v9 的做法是把两者对齐：
535	 *   PRESSING 只累加不滚，等到 LV_EVENT_REFR_START 这一刻才
536	 *   `_lv_obj_scroll_by_raw()` 一次性应用。每帧只滚一次、正好在画之前，
537	 *   帧间隔自然均匀。
538	 *
539	 *   对应源码：example/multimedia/lvgl/watch_v9/src/gui_apps/main/
540	 *   app_mainmenu.c 的 refr_start_cb()（第 1099 行）。
541	 *
542	 ****************************************************************************/
543	
544	static void refr_start_cb(lv_event_t *e)
545	{
546	  LV_UNUSED(e);
547	
548	  if (g_app.scroll_actived)
549	    {
550	      lv_obj_scroll_by_bounded(g_app.page,
551	                               g_app.scroll_sum.x,
552	                               g_app.scroll_sum.y,
553	                               LV_ANIM_OFF);
554	
555	      g_app.scroll_sum.x = 0;
556	      g_app.scroll_sum.y = 0;
557	    }
558	}
559	
560	static void refr_ready_cb(lv_event_t *e)
561	{
562	  LV_UNUSED(e);
563	
564	  if (g_app.scroll_actived)
565	    {
566	      perf_record(monotonic_us(),
567	                  &g_app.perf.first_frame_us,
568	                  &g_app.perf.last_frame_us,
569	                  &g_app.perf.frame_events,
570	                  &g_app.perf.max_frame_gap_us);
571	    }
572	}
