659	/****************************************************************************
660	 * Name: nearest_card
661	 *
662	 * Description:
663	 *   找离屏幕中心最近的卡片，松手后吸附到它。
664	 *   对应官方的 mainmenu_cell_predict_focus_icon()。
665	 *
666	 * Returned Value:
667	 *   最近的卡片对象，找不到时返回第一张。
668	 *
669	 ****************************************************************************/
670	
671	static lv_obj_t *nearest_card(void)
672	{
673	  lv_obj_t *best = g_app.cards[0];
674	  int32_t best_dist = INT32_MAX;
675	  int32_t scr_mid = SCR_H / 2;
676	  int i;
677	
678	  for (i = 0; i < CARD_COUNT; i++)
679	    {
680	      lv_area_t area;
681	      int32_t mid;
682	      int32_t dist;
683	
684	      lv_obj_get_coords(g_app.cards[i], &area);
685	      mid = (area.y1 + area.y2) / 2;
686	      dist = LV_ABS(mid - scr_mid);
687	
688	      if (dist < best_dist)
689	        {
690	          best_dist = dist;
691	          best = g_app.cards[i];
692	        }
693	    }
694	
695	  return best;
696	}
