698	/****************************************************************************
699	 * Name: build_ui
700	 *
701	 * Description:
702	 *   搭建卡片流。
703	 *
704	 *   关键是滚动容器的配置 —— 这决定了跟手手感：
705	 *
706	 *   - LV_SCROLL_SNAP_CENTER：松手后自动吸附到最近的卡片中心，
707	 *     照官方 watch_v9 蜂窝菜单（app_mainmenu.c:1424）的做法
708	 *   - LV_DIR_VER：只吃竖向手势，避免横向误触
709	 *   - scrollbar OFF：手表屏幕上滚动条没意义
710	 *
711	 *   滚动过程由 LVGL 直接跟触摸事件走，不经过脚本层；实际端到端延迟仍需
712	 *   用真机时间戳测量，不能由 LCD putarea 调用率推断。
713	 *
714	 ****************************************************************************/
715	
716	static void build_ui(void)
717	{
718	  lv_obj_t *screen = lv_screen_active();
719	  lv_obj_t *page;
720	
721	  lv_obj_set_style_bg_color(screen, COLOR_BG, LV_PART_MAIN);
722	  lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, LV_PART_MAIN);
723	  lv_obj_remove_flag(screen, LV_OBJ_FLAG_SCROLLABLE);
724	
725	  page = lv_obj_create(screen);
726	  lv_obj_remove_style_all(page);
727	  lv_obj_set_size(page, SCR_W, SCR_H);
728	  lv_obj_set_pos(page, 0, 0);
729	
730	  /* 卡片竖排，之间不留缝 —— 每张恰好铺满一屏 */
731	
732	  lv_obj_set_flex_flow(page, LV_FLEX_FLOW_COLUMN);
733	  lv_obj_set_style_pad_row(page, 0, LV_PART_MAIN);
734	  lv_obj_set_style_pad_all(page, 0, LV_PART_MAIN);
735	
736	  /* 吸附到卡片中心 + 只允许竖滑。
737	   *
738	   * SCROLLABLE 必须显式加回来 —— 上面的 lv_obj_remove_style_all()
739	   * 会把这个 flag 一起清掉，不加回去容器收不到滑动手势
740	   * （症状：只有每秒定时器刷新的 5 fps，滑动毫无反应）。
741	   */
742	
743	  lv_obj_add_flag(page, LV_OBJ_FLAG_SCROLLABLE);
744	  lv_obj_set_scroll_snap_y(page, LV_SCROLL_SNAP_CENTER);
745	  lv_obj_set_scroll_dir(page, LV_DIR_VER);
746	  lv_obj_set_scrollbar_mode(page, LV_SCROLLBAR_MODE_OFF);
747	
748	  g_app.page = page;
749	
750	  /* 手势接管 + 位移与渲染同步。这两个回调是跟手手感的核心，
751	   * 照官方 watch_v9 蜂窝菜单（app_mainmenu.c:1430 / 1432）挂法。
752	   */
753	
754	  lv_obj_add_event_cb(page, page_event_cb, LV_EVENT_ALL, NULL);
755	  lv_display_add_event_cb(lv_display_get_default(), refr_start_cb,
756	                          LV_EVENT_REFR_START, NULL);
757	  lv_display_add_event_cb(lv_display_get_default(), refr_ready_cb,
758	                          LV_EVENT_REFR_READY, NULL);
759	
760	  build_card_home();
761	  build_card_ride();
762	  build_card_alert();
763	  build_card_review();
764	
765	  /* 初始定位到第一张。ANIM_OFF 避免启动时看到一次滚动动画。 */
766	
767	  lv_obj_scroll_to_view(g_app.cards[0], LV_ANIM_OFF);
768	}
