770	/****************************************************************************
771	 * Name: update_tick
772	 *
773	 * Description:
774	 *   每秒刷新一次数据。
775	 *
776	 *   目前速度和距离是按骑行秒数模拟的（和快应用版一致），
777	 *   接真实传感器时替换 derive 部分即可，界面代码不用动。
778	 *
779	 ****************************************************************************/
780	
781	static void update_tick(lv_timer_t *timer)
782	{
783	  char buf[64];
784	  time_t now;
785	  struct tm tm_now;
786	  uint32_t sec;
787	  uint32_t minutes;
788	  int percent;
789	
790	  LV_UNUSED(timer);
791	
792	  /* --- 时钟 --- */
793	
794	  now = time(NULL);
795	  localtime_r(&now, &tm_now);
796	  snprintf(buf, sizeof(buf), "%02d:%02d", tm_now.tm_hour, tm_now.tm_min);
797	  lv_label_set_text(g_app.home.clock, buf);
798	
799	  /* --- 骑行计时 --- */
800	
801	  sec = ++g_app.ride_sec;
802	  minutes = sec / 60;
803	
804	  snprintf(buf, sizeof(buf), "%02" PRIu32 ":%02" PRIu32 ":%02" PRIu32,
805	           sec / 3600, (sec % 3600) / 60, sec % 60);
806	  lv_label_set_text(g_app.ride.elapsed, buf);
807	
808	  /* --- 派生数据（模拟，待接传感器）--- */
809	
810	  snprintf(buf, sizeof(buf), "%" PRIu32 ".%" PRIu32,
811	           15 + (sec % 7), sec % 10);
812	  lv_label_set_text(g_app.ride.speed, buf);
813	
814	  snprintf(buf, sizeof(buf), "%" PRIu32 ".%" PRIu32,
815	           sec * 4 / 1000, (sec * 4 / 100) % 10);
816	  lv_label_set_text(g_app.ride.distance, buf);
817	
818	  lv_label_set_text(g_app.ride.motion,
819	                    (sec % 10) < 5 ? "riding" : "cruising");
820	
821	  percent = (int)((uint64_t)sec * 100 / REST_CYCLE_SEC);
822	  if (percent > 100)
823	    {
824	      percent = 100;
825	    }
826	
827	  /* ANIM_ON：每秒一次的值变化走平滑过渡，比直接跳更顺眼 */
828	
829	  lv_bar_set_value(g_app.ride.bar, percent, LV_ANIM_ON);
830	
831	  /* --- 提醒卡片 --- */
832	
833	  snprintf(buf, sizeof(buf), "riding %" PRIu32 " min", minutes);
834	  lv_label_set_text(g_app.alert.minutes, buf);
835	
836	  /* --- 今日累计（暂用固定值，待接持久化）--- */
837	
838	  lv_label_set_text(g_app.home.distance, "12.5");
839	  lv_label_set_text(g_app.home.duration, "45");
840	  lv_label_set_text(g_app.home.calories, "180");
841	}
