843	/****************************************************************************
844	 * Public Functions
845	 ****************************************************************************/
846	
847	int main(int argc, FAR char *argv[])
848	{
849	  lv_nuttx_dsc_t info;
850	  lv_nuttx_result_t result;
851	#ifdef CONFIG_LV_USE_NUTTX_LIBUV
852	  lv_nuttx_uv_t uv_info;
853	  uv_loop_t ui_loop;
854	  void *uv_data;
855	  int ret;
856	#endif
857	
858	  LV_UNUSED(argc);
859	  LV_UNUSED(argv);
860	
861	  /* LVGL 是单实例的。快应用（vapp）在跑时已经占住显示驱动，
862	   * 两个实例抢驱动会得到 "disp refr_timer is NULL"。
863	   */
864	
865	  if (lv_is_initialized())
866	    {
867	      printf("velaride: LVGL already initialized (vapp running?).\n");
868	      printf("velaride: kill the vapp process first.\n");
869	      return EXIT_FAILURE;
870	    }
871	
872	  lv_init();
873	
874	  lv_nuttx_dsc_init(&info);
875	#ifdef CONFIG_LV_USE_NUTTX_LCD
876	  info.fb_path = "/dev/lcd0";
877	#endif
878	#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
879	  info.input_path = "/dev/input0";
880	#endif
881	
882	  lv_nuttx_init(&info, &result);
883	
884	  if (result.disp == NULL)
885	    {
886	      printf("velaride: display init failed\n");
887	      return EXIT_FAILURE;
888	    }
889	
890	  if (result.indev == NULL)
891	    {
892	      /* 没有触摸就只能看，不能滑 —— 提示但不退出 */
893	
894	      printf("velaride: WARNING no input device, swipe unavailable\n");
895	    }
896	  else
897	    {
898	      lv_indev_add_event_cb(result.indev, indev_diag_cb, LV_EVENT_ALL, NULL);
899	    }
900	
901	#ifdef CONFIG_LV_USE_NUTTX_LIBUV
902	  /* Use the same event-driven NuttX integration as the repository's
903	   * lvgldemo.  lv_nuttx_init() alone leaves the input device in timer mode,
904	   * coupling touch latency to LVGL rendering.  The libuv poll wakes LVGL as
905	   * soon as /dev/input0 becomes readable.
906	   */
907	
908	  memset(&ui_loop, 0, sizeof(ui_loop));
909	  ret = uv_loop_init(&ui_loop);
910	  if (ret < 0)
911	    {
912	      printf("velaride: uv loop init failed: %s\n", uv_strerror(ret));
913	      return EXIT_FAILURE;
914	    }
915	
916	  memset(&uv_info, 0, sizeof(uv_info));
917	  uv_info.loop = &ui_loop;
918	  uv_info.disp = result.disp;
919	  uv_info.indev = result.indev;
920	
921	  uv_data = lv_nuttx_uv_init(&uv_info);
922	  if (uv_data == NULL)
923	    {
924	      printf("velaride: LVGL libuv integration failed\n");
925	      uv_loop_close(&ui_loop);
926	      return EXIT_FAILURE;
927	    }
928	#endif
929	
930	  build_ui();
931	  update_tick(NULL);
932	  lv_timer_create(update_tick, 1000, NULL);
933	
934	#ifdef CONFIG_LV_USE_NUTTX_LIBUV
935	  printf("velaride: event-driven touch loop enabled\n");
936	  uv_run(&ui_loop, UV_RUN_DEFAULT);
937	  lv_nuttx_uv_deinit(&uv_data);
938	  uv_run(&ui_loop, UV_RUN_NOWAIT);
939	  uv_loop_close(&ui_loop);
940	#else
941	  while (1)
942	    {
943	      uint32_t idle = lv_timer_handler();
944	
945	      /* lv_timer_handler 返回距下次任务的毫秒数。返回 0 时给 1ms，
946	       * 避免空转把 CPU 占满 —— 滚动期间它会返回很小的值，
947	       * 所以不影响跟手。
948	       */
949	
950	      usleep((idle ? idle : 1) * 1000);
951	    }
952	#endif
953	
954	  return EXIT_SUCCESS;
955	}
