163	
164	static void gpu_lock(drv_epic_op_type_t ops,
165	                     void *p1,
166	                     void *p2,
167	                     void *p3)
168	{
169	#define CALC_LAYER_SIZE(layer) \
170	        (RT_ALIGN((layer)->total_width * (layer)->height * HAL_EPIC_GetColorDepth((layer)->color_mode), 8) >> 3)
171	#define GET_LAYER_SIZE(layer) \
172	        (EPIC_IS_EZIP_COLOR_MODE((layer)->color_mode))?((layer)->data_size):CALC_LAYER_SIZE(layer)
173	
174	    gpu_log_start(ops, p1, p2, p3);
175	
176	    RT_ASSERT((0 == drv_epic.gpu_fg_addr) && (0 == drv_epic.gpu_bg_addr) && (0 == drv_epic.gpu_mask_addr));
177	
178	    uint32_t mask_size = 0, fg_size = 0, bg_size = 0;
179	
180	    /*Get fg,bg address and output area*/
181	    switch (ops)
182	    {
183	    case DRV_EPIC_COLOR_BLEND:
184	    case DRV_EPIC_LETTER_BLEND:
185	    {
186	        EPIC_LayerConfigTypeDef *fg = p1;
187	        EPIC_LayerConfigTypeDef *bg = p2;
188	        EPIC_LayerConfigTypeDef *dst = p3;
189	        RT_ASSERT(NULL != dst);
190	
191	        EPIC_TransformCfgTypeDef *rot_cfg = &(fg->transform_cfg);
192	
193	        drv_epic.gpu_fg_addr = (uint32_t) fg->data;
194	        drv_epic.gpu_bg_addr = (uint32_t) bg->data;
195	
196	        bg_size = GET_LAYER_SIZE(bg);
197	        fg_size = GET_LAYER_SIZE(fg);
198	
199	        drv_epic.gpu_output_addr = (uint32_t) dst->data;
200	        drv_epic.gpu_output_size = CALC_LAYER_SIZE(dst);
201	    }
202	    break;
203	
204	    case DRV_EPIC_IMG_ROT:
205	    case DRV_EPIC_TRANSFORM:
206	    {
207	
208	        EPIC_LayerConfigTypeDef *input_layers = p1;
209	        uint8_t input_layer_cnt = *((uint8_t *)p2);
210	
211	
212	        EPIC_LayerConfigTypeDef *bg = input_layers + 0;
213	        EPIC_LayerConfigTypeDef *fg = input_layers + 1;
214	        EPIC_LayerConfigTypeDef *mask = input_layer_cnt > 2 ? input_layers + 2 : NULL;
215	        EPIC_LayerConfigTypeDef *dst = p3;
216	        RT_ASSERT(NULL != dst);
217	
218	        EPIC_TransformCfgTypeDef *rot_cfg = &(fg->transform_cfg);
219	
220	        if (mask)
221	        {
222	            drv_epic.gpu_mask_addr = (uint32_t) mask->data;
223	            mask_size = GET_LAYER_SIZE(mask);
224	        }
225	        drv_epic.gpu_fg_addr = (uint32_t) fg->data;
226	        drv_epic.gpu_bg_addr = (uint32_t) bg->data;
227	
228	        bg_size = GET_LAYER_SIZE(bg);
229	        fg_size = GET_LAYER_SIZE(fg);
230	
231	        drv_epic.gpu_output_addr = (uint32_t) dst->data;
232	        drv_epic.gpu_output_size = CALC_LAYER_SIZE(dst);
233	
234	    }
235	    break;
236	
237	    case DRV_EPIC_COLOR_FILL:
238	    {
239	
240	        EPIC_LayerConfigTypeDef *mask = p1;
241	
242	        EPIC_LayerConfigTypeDef *param = p3;
243	        RT_ASSERT(NULL != param);
244	
245	        drv_epic.gpu_output_addr = (uint32_t) param->data;
246	        drv_epic.gpu_output_size = CALC_LAYER_SIZE(param);
247	
248	        if (mask)
249	        {
250	            drv_epic.gpu_mask_addr = (uint32_t) mask->data;
251	            mask_size = GET_LAYER_SIZE(mask);
252	        }
253	
254	
255	    }
256	    break;
257	
258	    case DRV_EPIC_IMG_COPY:
259	    {
260	
261	        EPIC_BlendingDataType *fg = p1;
262	
263	        EPIC_BlendingDataType *dst = p3;
264	
265	        drv_epic.gpu_fg_addr = (uint32_t) fg->data;
266	        drv_epic.gpu_bg_addr = drv_epic.gpu_fg_addr;
267	        fg_size = GET_LAYER_SIZE(fg);
268	        bg_size = fg_size;
269	
270	        drv_epic.gpu_output_addr = (uint32_t) dst->data;
271	        drv_epic.gpu_output_size = CALC_LAYER_SIZE(dst);
272	    }
273	    break;
274	
275	    case DRV_EPIC_FILL_GRAD:
276	    {
277	        EPIC_GradCfgTypeDef *param = p3;
278	
279	        drv_epic.gpu_output_addr = (uint32_t) param->start;
280	        drv_epic.gpu_output_size = CALC_LAYER_SIZE(param);
281	    }
282	    break;
283	
284	    default:
285	        RT_ASSERT(0);
286	        break;
287	    }
288	
289	    drv_epic.gpu_last_op = ops;
290	
291	#ifdef PSRAM_CACHE_WB
292	    {
293	        if ((drv_epic.gpu_bg_addr != 0) && (0 == bg_size)) bg_size = UINT32_MAX;
294	        if ((drv_epic.gpu_fg_addr != 0) && (0 == fg_size)) fg_size = UINT32_MAX;
295	        if ((drv_epic.gpu_mask_addr != 0) && (0 == mask_size)) mask_size = UINT32_MAX;
296	
297	        int r = 0;
298	        if (bg_size)
299	            r = dcache_clean((void *)drv_epic.gpu_bg_addr, bg_size);
300	        if (fg_size && (r == 0))
301	            r = dcache_clean((void *)drv_epic.gpu_fg_addr, fg_size);
302	        if (mask_size && (r == 0))
303	            r = dcache_clean((void *)drv_epic.gpu_mask_addr, mask_size);
304	        if (drv_epic.gpu_output_size && (r == 0))
305	            r = dcache_clean((void *)drv_epic.gpu_output_addr, drv_epic.gpu_output_size);
306	    }
307	#endif
308	
309	    /* Lock GPU used flash*/
310	    rt_flash_lock(drv_epic.gpu_fg_addr);
311	
312	    if (rt_flash_get_handle_by_addr(drv_epic.gpu_fg_addr) != rt_flash_get_handle_by_addr(drv_epic.gpu_bg_addr))
313	        rt_flash_lock(drv_epic.gpu_bg_addr);
314	
315	    if ((rt_flash_get_handle_by_addr(drv_epic.gpu_fg_addr) != rt_flash_get_handle_by_addr(drv_epic.gpu_mask_addr))
316	            && (rt_flash_get_handle_by_addr(drv_epic.gpu_bg_addr) != rt_flash_get_handle_by_addr(drv_epic.gpu_mask_addr)))
317	        rt_flash_lock(drv_epic.gpu_mask_addr);
318	
319	
320	#ifdef BSP_USING_PM
321	    rt_pm_request(PM_SLEEP_MODE_IDLE);
322	    rt_pm_hw_device_start();
323	#endif /*BSP_USING_PM*/
324	
325	}
