327	static void gpu_unlock(void)
328	{
329	#ifdef BSP_USING_PM
330	    rt_pm_hw_device_stop();
331	    rt_pm_release(PM_SLEEP_MODE_IDLE);
332	#endif /*BSP_USING_PM*/
333	
334	
335	    /* UnLock GPU used flash*/
336	    rt_flash_unlock(drv_epic.gpu_fg_addr);
337	
338	    if (rt_flash_get_handle_by_addr(drv_epic.gpu_fg_addr) != rt_flash_get_handle_by_addr(drv_epic.gpu_bg_addr))
339	        rt_flash_unlock(drv_epic.gpu_bg_addr);
340	
341	    if ((rt_flash_get_handle_by_addr(drv_epic.gpu_fg_addr) != rt_flash_get_handle_by_addr(drv_epic.gpu_mask_addr))
342	            && (rt_flash_get_handle_by_addr(drv_epic.gpu_bg_addr) != rt_flash_get_handle_by_addr(drv_epic.gpu_mask_addr)))
343	        rt_flash_unlock(drv_epic.gpu_mask_addr);
344	
345	
346	    dcache_invalidate((void *)drv_epic.gpu_output_addr, drv_epic.gpu_output_size);
347	
348	
349	    drv_epic.gpu_fg_addr  = 0;
350	    drv_epic.gpu_bg_addr  = 0;
351	    drv_epic.gpu_mask_addr = 0;
352	
353	    drv_epic.gpu_output_addr = 0;
354	    drv_epic.gpu_output_size = 0;
355	
356	    gpu_log_stop();
357	}
