401	/* Bilinear interpolation of a single color channel at (x,y) within area */
402	static uint8_t grad_interp_ch(uint8_t c00, uint8_t c01, uint8_t c10, uint8_t c11,
403	                              int16_t x, int16_t y, const EPIC_AreaTypeDef *area)
404	{
405	    int32_t w = HAL_EPIC_AreaWidth(area);
406	    int32_t h = HAL_EPIC_AreaHeight(area);
407	    int32_t x_num = x - area->x0;
408	    int32_t y_num = y - area->y0;
409	
410	    int32_t top = (c00 * (w - x_num) + c01 * x_num) / w;
411	    int32_t bot = (c10 * (w - x_num) + c11 * x_num) / w;
412	
413	    return (uint8_t)((top * (h - y_num) + bot * y_num) / h);
414	}
415	
416	/* Recalculate a corner color at (x,y) based on full-area gradient corners */
417	static EPIC_ColorDef grad_interp_color(int16_t x, int16_t y, const EPIC_AreaTypeDef *area)
418	{
419	    EPIC_ColorDef c;
420	    c.ch.alpha = grad_interp_ch(drv_epic.grad_color[0][0].ch.alpha,
421	                                drv_epic.grad_color[0][1].ch.alpha,
422	                                drv_epic.grad_color[1][0].ch.alpha,
423	                                drv_epic.grad_color[1][1].ch.alpha, x, y, area);
424	    c.ch.color_r = grad_interp_ch(drv_epic.grad_color[0][0].ch.color_r,
425	                                  drv_epic.grad_color[0][1].ch.color_r,
426	                                  drv_epic.grad_color[1][0].ch.color_r,
427	                                  drv_epic.grad_color[1][1].ch.color_r, x, y, area);
428	    c.ch.color_g = grad_interp_ch(drv_epic.grad_color[0][0].ch.color_g,
429	                                  drv_epic.grad_color[0][1].ch.color_g,
430	                                  drv_epic.grad_color[1][0].ch.color_g,
431	                                  drv_epic.grad_color[1][1].ch.color_g, x, y, area);
432	    c.ch.color_b = grad_interp_ch(drv_epic.grad_color[0][0].ch.color_b,
433	                                  drv_epic.grad_color[0][1].ch.color_b,
434	                                  drv_epic.grad_color[1][0].ch.color_b,
435	                                  drv_epic.grad_color[1][1].ch.color_b, x, y, area);
436	    return c;
437	}
