440	static HAL_StatusTypeDef epic_split_render_next(uint8_t init)
441	{
442	    EPIC_AreaTypeDef *p_render_area = &drv_epic.split_rd.render_area;
443	    EPIC_AreaTypeDef *p_next_sub_area = &drv_epic.split_rd.next_render_area;
444	    drv_epic_op_type_t  cur_op = drv_epic.split_rd.op;
445	    EPIC_AreaTypeDef cur_render_area;
446	    HAL_StatusTypeDef ret;
447	
448	    //Get current rendering area
449	    if (init)
450	    {
451	        cur_render_area.x0 = p_render_area->x0;
452	        cur_render_area.x1 = MIN(p_render_area->x0 + EPIC_COORDINATES_MAX - 1, p_render_area->x1);
453	
454	        cur_render_area.y0 = p_render_area->y0;
455	        cur_render_area.y1 = MIN(p_render_area->y0 + EPIC_COORDINATES_MAX - 1, p_render_area->y1);
456	
457	        drv_epic.split_rd.next_render_area = cur_render_area;
458	    }
459	    else
460	    {
461	        cur_render_area = drv_epic.split_rd.next_render_area;
462	    }
463	
464	    //Move p_next_sub_area' to next area
465	    if (p_next_sub_area->x0 + EPIC_COORDINATES_MAX <= p_render_area->x1)
466	    {
467	        p_next_sub_area->x0 = p_next_sub_area->x0 + EPIC_COORDINATES_MAX;
468	        p_next_sub_area->x1 = MIN(p_next_sub_area->x0 + EPIC_COORDINATES_MAX - 1, p_render_area->x1);
469	    }
470	    else if (p_next_sub_area->y0 + EPIC_COORDINATES_MAX <= p_render_area->y1)
471	    {
472	        p_next_sub_area->x0 = p_render_area->x0;
473	        p_next_sub_area->x1 = MIN(p_next_sub_area->x0 + EPIC_COORDINATES_MAX - 1, p_render_area->x1);
474	
475	        p_next_sub_area->y0 = p_next_sub_area->y0 + EPIC_COORDINATES_MAX;
476	        p_next_sub_area->y1 = MIN(p_next_sub_area->y0 + EPIC_COORDINATES_MAX - 1, p_render_area->y1);
477	    }
478	    else
479	    {
480	        drv_epic.split_rd.op = DRV_EPIC_INVALID; //Render_area done.
481	    }
482	
483	
484	    //Clip dst layer to current rendering area
485	    EPIC_BlendingDataType *p_dst_layer = (EPIC_BlendingDataType *) &drv_epic.output_layer;
486	    const EPIC_AreaTypeDef *dst_area = &drv_epic.split_rd.dst_area;
487	    clip_layer_to_area(p_dst_layer, drv_epic.split_rd.dst_data,
488	                       dst_area->x0, dst_area->y0, &cur_render_area);
489	
490	
491	    //Start it.
492	    LOG_D("split_render [%s] "AreaString" data=0x%x", op_name(cur_op), AreaParams(&cur_render_area),
493	          p_dst_layer->data);
494	    EPIC_HandleTypeDef *h_epic = &drv_epic.epic_handle;
495	    switch (cur_op)
496	    {
497	    case DRV_EPIC_IMG_COPY:
498	    {
499	        EPIC_BlendingDataType *p_src_layer = (EPIC_BlendingDataType *) &drv_epic.input_layers[0];
500	
501	
502	        PRINT_LAYER_INFO(p_src_layer, "src");
503	        PRINT_LAYER_INFO(p_dst_layer, "dst");
504	        h_epic->XferCpltCallback = epic_cplt_callback;
505	        ret = HAL_EPIC_Copy_IT(h_epic, p_src_layer, p_dst_layer);
506	    }
507	    break;
508	
509	    case DRV_EPIC_COLOR_FILL:
510	    {
511	        LOG_D("fill color %02x%02x%02x", drv_epic.output_layer.color_r,
512	              drv_epic.output_layer.color_g,
513	              drv_epic.output_layer.color_b);
514	        for (uint8_t i = 0; i < drv_epic.input_layer_cnt; i++)
515	        {
516	            PRINT_LAYER_INFO(&drv_epic.input_layers[i], "src");
517	        }
518	        PRINT_LAYER_INFO(&drv_epic.output_layer, "dst");
519	        h_epic->XferCpltCallback = epic_cplt_callback;
520	        ret = HAL_EPIC_BlendStartEx_IT(h_epic, drv_epic.input_layers,
521	                                       drv_epic.input_layer_cnt, &drv_epic.output_layer);
522	    }
523	    break;
524	
525	    case DRV_EPIC_IMG_ROT:
526	    {
527	        for (uint8_t i = 0; i < drv_epic.input_layer_cnt; i++)
528	        {
529	            PRINT_LAYER_INFO(&drv_epic.input_layers[i], "src");
530	            PRINT_LAYER_EXTRA_INFO(&drv_epic.input_layers[i]);
531	        }
532	        PRINT_LAYER_INFO(&drv_epic.output_layer, "dst");
533	        h_epic->XferCpltCallback = epic_cplt_callback;
534	        ret = HAL_EPIC_BlendStartEx_IT(h_epic, drv_epic.input_layers,
535	                                       drv_epic.input_layer_cnt, &drv_epic.output_layer);
536	    }
537	    break;
538	
539	    case DRV_EPIC_TRANSFORM:
540	    {
541	        for (uint8_t i = 0; i < drv_epic.input_layer_cnt; i++)
542	        {
543	            PRINT_LAYER_INFO(&drv_epic.input_layers[i], "src");
544	            PRINT_LAYER_EXTRA_INFO(&drv_epic.input_layers[i]);
545	        }
546	        PRINT_LAYER_INFO(&drv_epic.output_layer, "dst");
547	
548	        ret = HAL_EPIC_Adv(h_epic, drv_epic.input_layers,
549	                           drv_epic.input_layer_cnt, &drv_epic.output_layer);
550	
551	    }
552	    break;
553	
554	    case DRV_EPIC_FILL_GRAD:
555	    {
556	        EPIC_GradCfgTypeDef param;
557	
558	        param.start = p_dst_layer->data;
559	        param.color_mode = p_dst_layer->color_mode;
560	        param.width = p_dst_layer->width;
561	        param.height = p_dst_layer->height;
562	        param.total_width = p_dst_layer->total_width;
563	
564	        /* Recalculate corner colors for current tile position */
565	        param.color[0][0] = grad_interp_color(cur_render_area.x0, cur_render_area.y0, p_render_area);
566	        param.color[0][1] = grad_interp_color(cur_render_area.x1, cur_render_area.y0, p_render_area);
567	        param.color[1][0] = grad_interp_color(cur_render_area.x0, cur_render_area.y1, p_render_area);
568	        param.color[1][1] = grad_interp_color(cur_render_area.x1, cur_render_area.y1, p_render_area);
569	
570	        LOG_D("EPIC Fill Grad buf=0x%x, cf=%d, total_w=%d w,h=%d,%d",
571	              param.start, param.color_mode, param.total_width,
572	              param.width, param.height);
573	
574	        h_epic->XferCpltCallback = epic_cplt_callback;
575	        ret = HAL_EPIC_FillGrad_IT(h_epic, &param);
576	
577	    }
578	    break;
579	
580	    default:
581	        RT_ASSERT(0);
582	        break;
583	    }
584	
585	    return ret;
586	}
