732	static rt_err_t wait_gpu_done(rt_int32_t time)
733	{
734	    rt_err_t err;
735	    cont_blend_reset();
736	    do
737	    {
738	        err = drv_gpu_take(time);
739	
740	        if (RT_EOK != err)
741	        {
742	            LOG_E("wait_gpu_done timeout(-2)? err=%d", err);
743	#ifndef __DEBUG__
744	            gpu_reset();
745	            epic_abort_callback(&drv_epic.epic_handle);
746	#else
747	            RT_ASSERT(0); //Raise an assertion in debug mode.
