1263	rt_err_t drv_epic_cont_blend(EPIC_LayerConfigTypeDef *input_layers,
1264	                             uint8_t input_layer_cnt,
1265	                             EPIC_LayerConfigTypeDef *output_canvas)
1266	{
1267	
1268	    RT_ASSERT((RT_NULL != output_canvas) && (RT_NULL != input_layers));
1269	
1270	    HAL_StatusTypeDef ret;
1271	    rt_err_t err;
1272	    EPIC_HandleTypeDef *h_epic = &drv_epic.epic_handle;
1273	    EPIC_AreaTypeDef blend_area;
1274	    EPIC_LayerConfigTypeDef *fg_layer = &input_layers[1];
1275	    EPIC_LayerConfigTypeDef *mask_layer = (3 == input_layer_cnt) ? &input_layers[2] : NULL;
1276	
1277	    blend_area.x0 = output_canvas->x_offset;
1278	    blend_area.y0 = output_canvas->y_offset;
1279	    blend_area.x1 = output_canvas->x_offset + output_canvas->width  - 1;
1280	    blend_area.y1 = output_canvas->y_offset + output_canvas->height - 1;
1281	
1282	    LOG_D("\r\n drv_epic_cont_blend dst=%p "AreaString, output_canvas->data, AreaParams(&blend_area));
1283	    for (uint8_t i = 0; i < input_layer_cnt; i++)
1284	    {
1285	        PRINT_LAYER_INFO(input_layers + i, "src");
1286	        PRINT_LAYER_EXTRA_INFO(input_layers + i);
1287	    }
1288	    PRINT_LAYER_INFO(output_canvas, "dst");
1289	
1290	    if (false == drv_epic.cont_mode)
1291	    {
1292	        err = wait_gpu_done(GPU_BLEND_EXP_MS);
1293	        if (RT_EOK != err) return err;
1294	
1295	        gpu_lock(DRV_EPIC_LETTER_BLEND, fg_layer, mask_layer, output_canvas);
1296	
1297	        ret = HAL_EPIC_ContBlendStart(h_epic, fg_layer, mask_layer, output_canvas);
1298	        drv_epic.cont_mode = true;
1299	    }
1300	    else
1301	    {
1302	        //Clean Dcache
1303	        int dcache_all_cleaned;
1304	        dcache_all_cleaned = mpu_dcache_clean(fg_layer->data, fg_layer->data_size);
1305	        if ((0 == dcache_all_cleaned) && (mask_layer != NULL))
1306	        {
1307	            dcache_all_cleaned = mpu_dcache_clean(mask_layer->data, mask_layer->data_size);
1308	        }
1309	
1310	        ret = HAL_EPIC_ContBlendRepeat(h_epic, fg_layer, mask_layer, output_canvas);
1311	    }
1312	
1313	    return (HAL_OK == ret) ? RT_EOK : RT_ERROR;
1314	}
