12	/* EPIC 硬件图形加速基准测试。
13	 *
14	 * 回答两个问题：
15	 *
16	 *   1. EPIC 能不能在 openvela/NuttX 上直接跑？
17	 *      思澈官方黄山派表盘示例走 EPIC 拿到丝滑效果，但那套代码依赖
18	 *      RT-Thread（rtthread.h / gui_app_fwk.h）。不过实测 bf0_hal_epic.c
19	 *      里 9 处 rtthread 引用全部是注释状态，HAL 层已被移植方清理成裸实现，
20	 *      只依赖 bf0_hal.h。所以理论上可以直接调，本程序验证这一点。
21	 *
22	 *   2. EPIC 比 CPU 快多少？
23	 *      实测背景：LVGL 软渲染下滑动只有 2.9 fps（纯色空卡片 7.1 fps），
24	 *      而 LCD 送屏仅占 17ms/帧，说明瓶颈在像素填充与合成。
25	 *      本程序用同一块 buffer 分别跑 CPU memset 和 EPIC 硬件填充，直接对比。
26	 *
27	 * 用法（NSH 下）：
28	 *
29	 *   epicbench            # 跑全部测试
30	 *
31	 * 输出示例：
32	 *
33	 *   EPIC_BENCH: init ok, instance=0x50080000
34	 *   EPIC_BENCH: fill  CPU=118ms  EPIC=6ms   speedup=19.6x
35	 *   EPIC_BENCH: blit  CPU=142ms  EPIC=9ms   speedup=15.8x
36	 */
37	
38	#include <nuttx/config.h>
39	
40	#include <stdio.h>
41	#include <stdlib.h>
42	#include <string.h>
43	#include <time.h>
44	#include <unistd.h>
45	#include <sched.h>
46	#include <errno.h>
47	#include <inttypes.h>
48	
49	#include <nuttx/cache.h>
50	#include <nuttx/irq.h>
51	#include <nuttx/arch.h>    /* up_enable_irq() */
52	#include <arch/irq.h>
53	
54	#include <sfconfig.h>      /* NX_IRQ()：芯片中断号 → NuttX 中断号 */
55	
56	#include "bf0_hal.h"
57	#include "bf0_hal_epic.h"
58	#include "bf0_hal_ezip.h"   /* HAL_EZIP_Init()，EPIC 的 Init 依赖 hezip */
59	
60	/****************************************************************************
61	 * Pre-processor Definitions
62	 ****************************************************************************/
63	
64	/* 测试区域尺寸。
65	 *
66	 * 不用全屏 390×450：EPIC buffer 必须放在 SRAM（0x2000_0000 段），
67	 * 官方示例 example/hal/epic/src/main.c 用 L2_NON_RET_BSS_SECT 就是这个原因。
68	 * 实测 buffer 放 PSRAM（0x6014_52c0）时 EPIC 启动后 state 停在 BUSY、
69	 * EOF_IRQ 恒为 0 —— EPIC 这个 DMA master 访问不到 PSRAM。
70	 *
71	 * 而 SRAM 只有 512KB 且已用 76%，塞不下两个 351KB 全屏 buffer。
72	 * 改成 200×200 只测单位像素吞吐，按比例外推到全屏，结论不受影响。
73	 */
74	
75	#define BENCH_W      100
76	#define BENCH_H      100
77	#define BENCH_BPP    2
78	#define BENCH_BYTES  ((size_t)BENCH_W * BENCH_H * BENCH_BPP)
79	
80	/* 全屏像素数，用于把测试结果外推成"相当于全屏多少 ms" */
81	
82	#define FULL_W       390
83	#define FULL_H       450
84	
85	/* 每项测试重复次数，取平均以抵掉单次抖动 */
86	
87	#define BENCH_ROUNDS 10
88	
89	/****************************************************************************
90	 * Private Data
91	 ****************************************************************************/
92	
93	static EPIC_HandleTypeDef g_epic;
94	
95	/* EZIP handle 必须给 —— HAL_EPIC_Init 第一行就是：
96	 *
97	 *   #ifdef HAL_EZIP_MODULE_ENABLED
98	 *       epic->hezip->user_data = (void *)epic;
99	 *   #endif
100	 *
101	 * 本板 HAL_EZIP_MODULE_ENABLED 是开的（bf0_hal_conf_hcpu.h:30），
102	 * hezip 为 NULL 时这里就是空指针写入。Init 仍会返回 HAL_OK，但硬件
103	 * 后续跑不完 —— 实测 state 停在 BUSY、EOF_IRQ 恒为 0。
104	 *
105	 * 官方示例 example/hal/epic/src/main.c 的顺序是：
106	 *   hezip = &ezip_handle; hezip->Instance = EZIP;
107	 *   HAL_EZIP_Init(hezip); 然后才 HAL_EPIC_Init。
108	 */
109	
110	static EZIP_HandleTypeDef g_ezip;
111	
112	/* EPIC 的源和目标 buffer。
113	 *
114	 * 必须是静态数组而不是 memalign 堆分配 —— NuttX 用户堆在 PSRAM 上，
115	 * 而 EPIC 访问不到 PSRAM。静态数组落在 .bss，链接进 SRAM。
116	 * 64 字节对齐是 cache line 要求，EPIC 作为 DMA master 需要。
117	 */
118	
119	static uint8_t g_buf_a[BENCH_BYTES] __attribute__((aligned(64)));
120	static uint8_t g_buf_b[BENCH_BYTES] __attribute__((aligned(64)));
121	
122	/* EPIC 完成标志。HAL 的阻塞版接口内部自己轮询，这里只用于中断版验证。 */
123	
124	static volatile bool g_epic_done;
125	
126	/****************************************************************************
127	 * Private Functions
128	 ****************************************************************************/
129	
130	/****************************************************************************
131	 * Name: now_us
132	 *
133	 * Description:
134	 *   单调时钟当前值（微秒）。基准测试全部用它计时，避免 RTC 被调整影响。
135	 *
136	 ****************************************************************************/
137	
138	static uint64_t now_us(void)
139	{
140	  struct timespec ts;
141	
142	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
143	    {
144	      return 0;
145	    }
146	
147	  return (uint64_t)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
148	}
149	
150	/****************************************************************************
151	 * Name: epic_cplt_cb
152	 *
153	 * Description:
154	 *   EPIC 传输完成回调，供中断版接口使用。
155	 *
156	 ****************************************************************************/
157	
158	static void epic_cplt_cb(EPIC_HandleTypeDef *epic)
159	{
160	  (void)epic;
161	  g_epic_done = true;
162	}
163	
164	/****************************************************************************
165	 * Name: epic_isr
166	 *
167	 * Description:
168	 *   EPIC 中断服务例程。HAL 只提供 HAL_EPIC_IRQHandler，挂到 NuttX 向量表
169	 *   这一步得自己做 —— 接法照 sf32lb_lcd.c 里 LCDC1_IRQn 的写法。
170	 *
171	 *   不接中断的后果：中断版接口（Copy_IT / FillStart_IT）永远等不到完成
172	 *   回调；阻塞版接口内部也依赖中断清状态，实测跑分会在 8.8ms 和 23ms
173	 *   之间跳，数字不可信。
174	 *
175	 ****************************************************************************/
176	
177	static int epic_isr(int irq, FAR void *context, FAR void *arg)
178	{
179	  (void)irq;
180	  (void)context;
181	
182	  HAL_EPIC_IRQHandler((EPIC_HandleTypeDef *)arg);
183	  return OK;
184	}
185	
186	/****************************************************************************
187	 * Name: epic_wait_done
188	 *
189	 * Description:
190	 *   等 EPIC 完成回调。设上限避免中断没接上时死等。
191	 *   不用 usleep 让出 CPU —— EPIC 单次操作只有毫秒级，usleep 的调度延迟
192	 *   （至少一个 tick，1ms）会把测量结果整体抬高。忙等更准。
193	 *
194	 * Returned Value:
195	 *   完成返回 true，超时返回 false 并打印诊断。
196	 *
197	 ****************************************************************************/
198	
199	static bool epic_wait_done(const char *what)
200	{
201	  /* 等 EPIC 空闲。判据是 handle 的 State 回到 READY，而不是等自己的
202	   * XferCpltCallback —— 实测 buffer 放对（SRAM）之后 State 已经能正常
203	   * 回到 READY=1，说明硬件跑完了，但用户回调没被调到。
204	   *
205	   * 原因是 HAL 内部用 IntXferCpltCallback 处理完成事件，XferCpltCallback
206	   * 只在特定 api_type 下转发；阻塞版接口（HAL_EPIC_FillStart）本身就自带
207	   * 轮询等待，返回时已经完成。所以这里只做兜底确认，不依赖中断路径。
208	   */
209	
210	  uint32_t spins = 0;
211	
212	  while (g_epic.State != HAL_EPIC_STATE_READY && !g_epic_done)
213	    {
214	      if (++spins > 200000)
215	        {
216	          printf("EPIC_BENCH: %s 未完成，state=%d err=%" PRIu32 "\n",
217	                 what, (int)g_epic.State, g_epic.ErrorCode);
218	          return false;
219	        }
220	
221	      if ((spins & 0xff) == 0)
222	        {
223	          sched_yield();
224	        }
225	    }
226	
227	  return true;
228	}
229	
230	/****************************************************************************
231	 * Name: bench_cpu_fill
232	 *
233	 * Description:
234	 *   CPU 填充基准：整屏填成单色。这是 LVGL 软渲染画纯色矩形时做的事，
235	 *   用 memset 已经是 CPU 能做到的最快路径（RGB565 高低字节相同时成立），
236	 *   所以这个数字是 CPU 侧的乐观上界。
237	 *
238	 * Returned Value:
239	 *   平均单次耗时（微秒）。
240	 *
241	 ****************************************************************************/
242	
243	static uint64_t bench_cpu_fill(uint8_t *buf)
244	{
245	  uint64_t t0 = now_us();
246	  int i;
247	
248	  for (i = 0; i < BENCH_ROUNDS; i++)
249	    {
250	      /* 0x1F 高低字节相同，memset 能正确铺出 RGB565 的蓝色 */
251	
252	      memset(buf, 0x1f, BENCH_BYTES);
253	    }
254	
255	  return (now_us() - t0) / BENCH_ROUNDS;
256	}
257	
258	/****************************************************************************
259	 * Name: bench_epic_fill
260	 *
261	 * Description:
262	 *   EPIC 硬件填充基准，与 bench_cpu_fill 填同样大小的区域。
263	 *
264	 * Returned Value:
265	 *   平均单次耗时（微秒），失败返回 0。
266	 *
267	 ****************************************************************************/
268	
269	static uint64_t bench_epic_fill(uint8_t *buf)
270	{
271	  EPIC_FillingCfgTypeDef cfg;
272	  uint64_t t0;
273	  int i;
274	
275	  t0 = now_us();
276	
277	  for (i = 0; i < BENCH_ROUNDS; i++)
278	    {
279	      HAL_EPIC_FillDataInit(&cfg);
280	
281	      cfg.start       = buf;
282	      cfg.color_mode  = EPIC_COLOR_RGB565;
283	      cfg.width       = BENCH_W;
284	      cfg.height      = BENCH_H;
285	      cfg.total_width = BENCH_W;
286	      cfg.color_r     = 0x00;
287	      cfg.color_g     = 0x00;
288	      cfg.color_b     = 0xff;
289	      cfg.alpha       = 255;
290	
291	      /* EPIC 是 DMA 类硬件，写之前得让它看到最新内存内容，
292	       * 完成后要让 CPU 看到硬件写入的结果。
293	       */
294	
295	      up_clean_dcache((uintptr_t)buf, (uintptr_t)buf + BENCH_BYTES);
296	
297	      /* 用中断版而非阻塞版：阻塞版内部也依赖中断清状态，
298	       * 中断没接时跑分会在 8.8ms 和 23ms 之间跳。中断版配合
299	       * 自己等标志位，能确保测到的是硬件真实完成时间。
300	       */
301	
302	      /* 用阻塞版 —— 官方示例 example/hal/epic/src/main.c 就是这么调的，
303	       * 它内部自己轮询等硬件完成，返回时结果已经可用。
304	       * 中断版（_IT）需要 HAL 的 IntXferCpltCallback 链路，多一层不确定性。
305	       */
306	
307	      g_epic_done = false;
308	
309	      if (HAL_EPIC_FillStart(&g_epic, &cfg) != HAL_OK)
310	        {
311	          printf("EPIC_BENCH: HAL_EPIC_FillStart failed, state=%d err=%"
312	                 PRIu32 "\n", (int)g_epic.State, g_epic.ErrorCode);
313	          return 0;
314	        }
315	
316	      if (!epic_wait_done("fill"))
317	        {
318	          return 0;
319	        }
320	
321	      up_invalidate_dcache((uintptr_t)buf, (uintptr_t)buf + BENCH_BYTES);
322	    }
323	
324	  return (now_us() - t0) / BENCH_ROUNDS;
325	}
326	
327	/****************************************************************************
328	 * Name: bench_cpu_blit
329	 *
330	 * Description:
331	 *   CPU 整屏拷贝基准。滑动时 LVGL 要把卡片内容搬到新位置，本质是这个操作。
332	 *
333	 * Returned Value:
334	 *   平均单次耗时（微秒）。
335	 *
336	 ****************************************************************************/
337	
338	static uint64_t bench_cpu_blit(uint8_t *dst, const uint8_t *src)
339	{
340	  uint64_t t0 = now_us();
341	  int i;
342	
343	  for (i = 0; i < BENCH_ROUNDS; i++)
344	    {
345	      memcpy(dst, src, BENCH_BYTES);
346	    }
347	
348	  return (now_us() - t0) / BENCH_ROUNDS;
349	}
350	
351	/****************************************************************************
352	 * Name: bench_epic_blit
353	 *
354	 * Description:
355	 *   EPIC 整屏拷贝基准，对应 HAL_EPIC_Copy_IT。
356	 *   用中断版是因为 HAL 没提供阻塞版 Copy，需要自己等完成标志。
357	 *
358	 * Returned Value:
359	 *   平均单次耗时（微秒），失败返回 0。
360	 *
361	 ****************************************************************************/
362	
363	static uint64_t bench_epic_blit(uint8_t *dst, uint8_t *src)
364	{
365	  EPIC_BlendingDataType s;
366	  EPIC_BlendingDataType d;
367	  uint64_t t0;
368	  int i;
369	
370	  t0 = now_us();
371	
372	  for (i = 0; i < BENCH_ROUNDS; i++)
373	    {
374	      memset(&s, 0, sizeof(s));
375	      memset(&d, 0, sizeof(d));
376	
377	      s.data        = src;
378	      s.color_mode  = EPIC_COLOR_RGB565;
379	      s.width       = BENCH_W;
380	      s.height      = BENCH_H;
381	      s.total_width = BENCH_W;
382	
383	      d.data        = dst;
384	      d.color_mode  = EPIC_COLOR_RGB565;
385	      d.width       = BENCH_W;
386	      d.height      = BENCH_H;
387	      d.total_width = BENCH_W;
388	
389	      up_clean_dcache((uintptr_t)src, (uintptr_t)src + BENCH_BYTES);
390	      up_clean_dcache((uintptr_t)dst, (uintptr_t)dst + BENCH_BYTES);
391	
392	      g_epic_done = false;
393	
394	      if (HAL_EPIC_Copy_IT(&g_epic, &s, &d) != HAL_OK)
395	        {
396	          printf("EPIC_BENCH: HAL_EPIC_Copy_IT failed, state=%d err=%" PRIu32 "\n",
397	                 (int)g_epic.State, g_epic.ErrorCode);
398	          return 0;
399	        }
400	
401	      if (!epic_wait_done("blit"))
402	        {
403	          return 0;
404	        }
405	
406	      up_invalidate_dcache((uintptr_t)dst, (uintptr_t)dst + BENCH_BYTES);
407	    }
408	
409	  return (now_us() - t0) / BENCH_ROUNDS;
410	}
