412	/****************************************************************************
413	 * Name: report
414	 *
415	 * Description:
416	 *   打印一项对比结果。加速比用定点算，避免引入浮点格式化。
417	 *
418	 ****************************************************************************/
419	
420	static void report(const char *name, uint64_t cpu_us, uint64_t epic_us)
421	{
422	  /* 测试区域是 200×200，按像素数外推到全屏 390×450，
423	   * 这样能直接和实测的送屏 17ms / 帧率数据对比。
424	   */
425	
426	  const uint32_t scale_num = (uint32_t)FULL_W * FULL_H;
427	  const uint32_t scale_den = (uint32_t)BENCH_W * BENCH_H;
428	
429	  if (epic_us == 0)
430	    {
431	      printf("EPIC_BENCH: %-4s CPU=%" PRIu64 "us  EPIC=FAILED\n",
432	             name, cpu_us);
433	      return;
434	    }
435	
436	  {
437	    uint32_t ratio_x10 = (uint32_t)(cpu_us * 10 / epic_us);
438	    uint32_t cpu_full_ms = (uint32_t)(cpu_us * scale_num / scale_den / 1000);
439	    uint32_t epic_full_ms = (uint32_t)(epic_us * scale_num / scale_den / 1000);
440	
441	    printf("EPIC_BENCH: %-4s CPU=%" PRIu64 "us  EPIC=%" PRIu64
442	           "us  speedup=%" PRIu32 ".%" PRIu32 "x"
443	           "   [full screen: CPU=%" PRIu32 "ms EPIC=%" PRIu32 "ms]\n",
444	           name, cpu_us, epic_us, ratio_x10 / 10, ratio_x10 % 10,
445	           cpu_full_ms, epic_full_ms);
446	  }
447	}
