449	/****************************************************************************
450	 * Public Functions
451	 ****************************************************************************/
452	
453	int main(int argc, FAR char *argv[])
454	{
455	  uint8_t *buf_a = g_buf_a;
456	  uint8_t *buf_b = g_buf_b;
457	  int ret = EXIT_FAILURE;
458	
459	  (void)argc;
460	  (void)argv;
461	
462	  printf("EPIC_BENCH: %dx%d RGB565, %zu bytes, %d rounds\n",
463	         BENCH_W, BENCH_H, BENCH_BYTES, BENCH_ROUNDS);
464	
465	  memset(buf_a, 0xa5, BENCH_BYTES);
466	  memset(buf_b, 0x00, BENCH_BYTES);
467	
468	  /* 打地址确认落在 SRAM（0x2000_xxxx）而不是 PSRAM（0x6000_xxxx）。
469	   * EPIC 访问不到 PSRAM —— 这是之前四次失败的真正原因。
470	   */
471	
472	  printf("EPIC_BENCH: buf_a=%p buf_b=%p (SRAM 应为 0x2xxxxxxx)\n",
473	         buf_a, buf_b);
474	
475	  /* --- EPIC 初始化 -------------------------------------------------- */
476	
477	  memset(&g_epic, 0, sizeof(g_epic));
478	  memset(&g_ezip, 0, sizeof(g_ezip));
479	
480	  /* 顺序照官方示例 example/hal/epic/src/main.c：
481	   * EZIP 先就位再 Init EPIC，否则 HAL_EPIC_Init 会往 NULL 写。
482	   */
483	
484	  g_epic.hezip = &g_ezip;
485	  g_epic.hezip->Instance = EZIP;
486	
487	  if (HAL_EZIP_Init(g_epic.hezip) != HAL_OK)
488	    {
489	      printf("EPIC_BENCH: HAL_EZIP_Init 失败\n");
490	      goto out;
491	    }
492	
493	  g_epic.Instance = EPIC;
494	
495	  if (HAL_EPIC_Init(&g_epic) != HAL_OK)
496	    {
497	      printf("EPIC_BENCH: HAL_EPIC_Init 失败 err=%" PRIu32 "\n",
498	             g_epic.ErrorCode);
499	      printf("EPIC_BENCH: 结论 —— EPIC 在当前固件上起不来\n");
500	      goto out;
501	    }
502	
503	  printf("EPIC_BENCH: init ok, instance=%p state=%d\n",
504	         g_epic.Instance, (int)g_epic.State);
505	
506	  /* 挂中断。HAL_EPIC_Init 只开时钟和配寄存器，向量表这步 HAL 不管。 */
507	
508	  g_epic.XferCpltCallback = epic_cplt_cb;
509	
510	  if (irq_attach(NX_IRQ(EPIC_IRQn), epic_isr, &g_epic) != 0)
511	    {
512	      printf("EPIC_BENCH: irq_attach(EPIC_IRQn=%d) 失败\n", (int)EPIC_IRQn);
513	      goto out;
514	    }
515	
516	  up_enable_irq(NX_IRQ(EPIC_IRQn));
517	  printf("EPIC_BENCH: irq attached, EPIC_IRQn=%d nx_irq=%d\n",
518	         (int)EPIC_IRQn, NX_IRQ(EPIC_IRQn));
519	
520	  /* --- 填充对比 ----------------------------------------------------- */
521	
522	  report("fill", bench_cpu_fill(buf_a), bench_epic_fill(buf_a));
523	
524	  /* --- 拷贝对比 ----------------------------------------------------- */
525	
526	  report("blit", bench_cpu_blit(buf_b, buf_a), bench_epic_blit(buf_b, buf_a));
527	
528	  ret = EXIT_SUCCESS;
529	
530	out:
531	  /* buffer 是静态数组，不需要 free */
532	
533	  return ret;
534	}
