113	static inline bool cf_supported(lv_color_format_t cf, uint32_t flags)
114	{
115	    //Ezip/Jpeg images
116	    if ((LV_COLOR_FORMAT_RAW == cf || LV_COLOR_FORMAT_RAW_ALPHA == cf) && (0 != (flags & (LV_IMAGE_FLAGS_EZIP | LV_IMAGE_FLAGS_JPEG))))
117	        return true;
118	    //Normal images
119	    if (LV_COLOR_FORMAT_RGB565 == cf || LV_COLOR_FORMAT_ARGB8565 == cf ||
120	            LV_COLOR_FORMAT_RGB888 == cf || LV_COLOR_FORMAT_ARGB8888 == cf ||
121	            LV_COLOR_FORMAT_XRGB8888 == cf)
122	        return true;
123	
124	#ifdef EPIC_SUPPORT_A8
125	    if (LV_COLOR_FORMAT_A8 == cf) return true;
126	#endif /*EPIC_SUPPORT_A8*/
127	
128	#ifdef EPIC_SUPPORT_MASK
129	    if (LV_COLOR_FORMAT_RGB565A8 == cf) return true;
130	#endif
131	
132	#ifdef EPIC_SUPPORT_A4
133	    if (LV_COLOR_FORMAT_A4 == cf) return true;
134	#endif /*EPIC_SUPPORT_A4*/
135	
136	#ifdef EPIC_SUPPORT_A2
137	    if (LV_COLOR_FORMAT_A2 == cf) return true;
138	#endif /*EPIC_SUPPORT_A2*/
139	
140	#ifdef EPIC_SUPPORT_L8
141	    if ((LV_COLOR_FORMAT_I8 == cf) || (LV_COLOR_FORMAT_L8 == cf)) return true;
142	#endif /*EPIC_SUPPORT_L8*/
143	
144	#ifdef EPIC_SUPPORT_YUV
145	    if (LV_COLOR_FORMAT_I420 == cf || LV_COLOR_FORMAT_YUY2 == cf || LV_COLOR_FORMAT_UYVY == cf)
146	        return true;
147	#endif /*EPIC_SUPPORT_YUV*/
148	
149	
150	    return false;
151	}
