153	static int32_t evaluate(lv_draw_unit_t *draw_unit, lv_draw_task_t *t)
154	{
155	    lv_draw_epic_unit_t *draw_epic_unit = (lv_draw_epic_unit_t *) draw_unit;
156	
157	#ifdef DEBUG_LV_DRAW_EPIC_ENABLED_FUNCTION
158	    if (0 == (g_enable_epic & (1 << (t->type))))
159	    {
160	        return 0;
161	    }
162	#endif
163	
164	    switch (t->type)
165	    {
166	    case LV_DRAW_TASK_TYPE_FILL:
167	    {
168	        const lv_draw_fill_dsc_t *draw_dsc = (const lv_draw_fill_dsc_t *) t->draw_dsc;
169	
170	        if (draw_dsc->radius != 0)
171	            return 0;
172	
173	        if ((LV_GRADIENT_MAX_STOPS > 2) && (draw_dsc->grad.dir != (lv_grad_dir_t)LV_GRAD_DIR_NONE))
174	            return 0;
175	
176	        if (draw_dsc->grad.dir != LV_GRAD_DIR_NONE)
177	        {
178	            lv_layer_t *target_layer = t->target_layer;
179	            if (target_layer)
180	            {
181	                lv_color_format_t dest_cf = target_layer->color_format;
182	                uint32_t epic_cf = lv_img_2_epic_cf(dest_cf);
183	                if (!EPIC_SUPPROT_OUT_FORMAT(epic_cf))
184	                {
185	                    return 0;
186	                }
187	            }
188	        }
189	
190	        if (t->preference_score > 70)
191	        {
192	            t->preference_score = 70;
193	            t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
194	        }
195	        return 1;
196	    }
197	#if 0
198	    case LV_DRAW_TASK_TYPE_LINE:
199	    case LV_DRAW_TASK_TYPE_ARC:
200	        if (t->preference_score > 90)
201	        {
202	            t->preference_score = 90;
203	            t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
204	        }
205	        return 1;
206	
207	#endif
208	#ifdef EPIC_SUPPORT_A8
209	    case LV_DRAW_TASK_TYPE_LABEL:
210	    {
211	        const lv_draw_label_dsc_t *label_dsc = (const lv_draw_label_dsc_t *)t->draw_dsc;
212	        
213	        #if LV_USE_FREETYPE && LV_USE_VECTOR_GRAPHIC && LV_USE_THORVG
214	        lv_font_glyph_dsc_t glyph_dsc;
215	        if (label_dsc->font && 
216	            lv_font_get_glyph_dsc(label_dsc->font, &glyph_dsc, label_dsc->text[0], '\0') &&
217	            glyph_dsc.format == LV_FONT_GLYPH_FORMAT_VECTOR) {
218	            return 0; // No vector font processing.
219	        }
220	        #endif
221	        
222	        if (t->preference_score > 95) {
223	            t->preference_score = 95;
224	            t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
225	        }
226	        return 1;
227	    }
228	#endif /*EPIC_SUPPORT_A8*/
229	
230	    case LV_DRAW_TASK_TYPE_BORDER:
231	    {
232	        const lv_draw_border_dsc_t *draw_dsc = (lv_draw_border_dsc_t *) t->draw_dsc;
233	
234	        if (draw_dsc->side != (lv_border_side_t)LV_BORDER_SIDE_FULL)
235	            return 0;
236	
237	        if (draw_dsc->radius != 0)
238	            return 0;
239	
240	        if (t->preference_score > 90)
241	        {
242	            t->preference_score = 90;
243	            t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
244	        }
245	        return 1;
246	    }
247	
248	
249	    case LV_DRAW_TASK_TYPE_LAYER:
250	    {
251	        const lv_draw_image_dsc_t *draw_dsc = (const lv_draw_image_dsc_t *) t->draw_dsc;
252	        lv_layer_t *layer_to_draw = (lv_layer_t *)draw_dsc->src;
253	
254	        bool has_recolor = (draw_dsc->recolor_opa != LV_OPA_TRANSP);
255	        bool has_transform = (draw_dsc->rotation != 0 || draw_dsc->scale_x != LV_SCALE_NONE ||
256	                              draw_dsc->scale_y != LV_SCALE_NONE);
257	
258	        if (has_recolor
259	                || (!cf_supported(layer_to_draw->color_format, 0))
260	           )
261	            return 0;
262	        if ((LV_COLOR_FORMAT_RGB565A8 == layer_to_draw->color_format) && has_transform)
263	            return 0;
264	
265	        if (t->preference_score > 80)
266	        {
267	            t->preference_score = 80;
268	            t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
269	        }
270	        return 1;
271	    }
272	
273	    case LV_DRAW_TASK_TYPE_IMAGE:
274	    {
275	        lv_draw_image_dsc_t *draw_dsc = (lv_draw_image_dsc_t *) t->draw_dsc;
276	
277	        bool has_recolor = (draw_dsc->recolor_opa != LV_OPA_TRANSP);
278	        bool has_transform = (draw_dsc->rotation != 0 || draw_dsc->scale_x != LV_SCALE_NONE ||
279	                              draw_dsc->scale_y != LV_SCALE_NONE);
280	
281	        if (has_recolor
282	                || (!cf_supported(draw_dsc->header.cf, draw_dsc->header.flags))
283	           )
284	            return 0;
285	
286	        if ((LV_COLOR_FORMAT_RGB565A8 == draw_dsc->header.cf) && has_transform)
287	            return 0;
288	
289	        if (t->preference_score > 80)
290	        {
291	            t->preference_score = 80;
292	            t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
293	        }
294	        return 1;
295	    }
296	    default:
297	        return 0;
298	    }
299	
300	    return 0;
301	}
