304	static int32_t dispatch(lv_draw_unit_t *draw_unit, lv_layer_t *layer)
305	{
306	    lv_draw_epic_unit_t *draw_epic_unit = (lv_draw_epic_unit_t *) draw_unit;
307	
308	    /* Try to get an ready to draw. */
309	    lv_draw_task_t *t = lv_draw_get_next_available_task(layer, NULL, DRAW_UNIT_ID_EPIC);
310	
311	    if (t == NULL)
312	        return LV_DRAW_UNIT_IDLE;
313	
314	#if 0
315	    /*Use sw draw unit if EPIC is busy*/
316	    if ((draw_epic_unit->task_act) && (DRAW_UNIT_ID_EPIC == t->preferred_draw_unit_id))
317	    {
318	        int32_t ret;
319	        t->preferred_draw_unit_id = LV_DRAW_UNIT_NONE;//Let sw unit pick this layer
320	        ret = draw_epic_unit->p_sw_unit->dispatch_cb(draw_epic_unit->p_sw_unit, layer);
321	
322	        if (ret != 1)
323	        {
324	            t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC; //Restore preferred id to EPIC.
325	        }
326	        return ret;
327	    }
328	#else
329	    /*Return immediately if it's busy with draw task*/
330	    if (draw_epic_unit->task_act)
331	    {
332	        return 0;
333	    }
334	#endif /* 0 */
335	
336	    if (lv_draw_get_unit_count() > 1)
337	    {
338	        /* Let the SW unit to draw this task. */
339	        if (t->preferred_draw_unit_id != DRAW_UNIT_ID_EPIC)
340	            return LV_DRAW_UNIT_IDLE;
341	    }
342	    else
343	    {
344	        /* Fake unsupported tasks as ready. */
345	        if (t->preferred_draw_unit_id != DRAW_UNIT_ID_EPIC)
346	        {
347	            t->state = LV_DRAW_TASK_STATE_FINISHED;
348	
349	            /* Request a new dispatching as it can get a new task. */
350	            lv_draw_dispatch_request();
351	
352	            return 1;
353	        }
354	    }
355	
356	    void *buf = lv_draw_layer_alloc_buf(layer);
357	    if (buf == NULL)
358	        return LV_DRAW_UNIT_IDLE;
359	
360	    t->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
361	    draw_epic_unit->task_act = t;
362	
363	#if LV_USE_OS
364	    /* Let the render thread work. */
365	    if (draw_epic_unit->inited)
366	        lv_thread_sync_signal(&draw_epic_unit->sync);
367	#else
368	    execute_drawing(draw_epic_unit);
369	
370	    draw_epic_unit->task_act->state = LV_DRAW_TASK_STATE_FINISHED;
371	    draw_epic_unit->task_act = NULL;
372	
373	    /* The draw unit is free now. Request a new dispatching as it can get a new task. */
374	    lv_draw_dispatch_request();
375	#endif
376	
377	    return 1;
378	}
