380	static void execute_drawing(lv_draw_epic_unit_t *u)
381	{
382	    lv_draw_task_t *t = u->task_act;
383	
384	    int ret = (int)drv_epic_wait_done();
385	    if (ret > 0)
386	    {
387	        LV_LOG_ERROR("sf32lb_epic_waitdone error %d", ret);
388	        LV_ASSERT(0);
389	    }
390	
391	    LV_EPIC_LOG("_epic_execute_drawing %d ", t->type);
392	    lv_epic_print_area_info("src_area", &t->area);
393	    lv_epic_print_layer_info(t);
394	
395	    switch (t->type)
396	    {
397	
398	    case LV_DRAW_TASK_TYPE_FILL: /*0*/
399	        lv_draw_epic_fill(t, t->draw_dsc, &t->area);
400	        break;
401	    case LV_DRAW_TASK_TYPE_BORDER:/*1*/
402	        lv_draw_epic_border(t, t->draw_dsc, &t->area);
403	        break;
404	
405	
406	    case LV_DRAW_TASK_TYPE_LABEL:/*4*/
407	        lv_draw_epic_label(t, t->draw_dsc, &t->area);
408	        break;
409	
410	    case LV_DRAW_TASK_TYPE_IMAGE: /*5*/
411	        lv_draw_epic_img(t, t->draw_dsc, &t->area);
412	        break;
413	    case LV_DRAW_TASK_TYPE_LAYER: /*6*/
414	        lv_draw_epic_layer(t, t->draw_dsc, &t->area);
415	        break;
416	#if 0
417	
418	
419	    case LV_DRAW_TASK_TYPE_LINE:/*7*/
420	        lv_draw_epic_line(t, t->draw_dsc);
421	        break;
422	
423	#endif
424	    case LV_DRAW_TASK_TYPE_ARC:/*8*/
425	        lv_draw_epic_arc(t, t->draw_dsc, &t->area);
426	        break;
427	    default:
428	        break;
429	    }
430	
431	    drv_epic_wait_done();
432	
433	#if LV_USE_PARALLEL_DRAW_DEBUG
434	    /*Layers manage it for themselves*/
435	    if (t->type != LV_DRAW_TASK_TYPE_LAYER)
436	    {
437	        lv_area_t draw_area;
438	        if (!lv_area_intersect(&draw_area, &t->area, t->clip_area)) return;
439	
440	        int32_t idx = t->draw_unit->idx;
441	        lv_draw_rect_dsc_t rect_dsc;
442	        lv_draw_rect_dsc_init(&rect_dsc);
443	        rect_dsc.bg_color = lv_palette_main(idx % LV_PALETTE_LAST);
444	        rect_dsc.border_color = rect_dsc.bg_color;
445	        rect_dsc.bg_opa = LV_OPA_10;
446	        rect_dsc.border_opa = LV_OPA_80;
447	        rect_dsc.border_width = 1;
448	        lv_draw_epic_fill(t, &rect_dsc, &draw_area);
449	
450	        lv_point_t txt_size;
451	        lv_text_get_size(&txt_size, "W", LV_FONT_DEFAULT, 0, 0, 100, LV_TEXT_FLAG_NONE);
452	
453	        lv_area_t txt_area;
454	        txt_area.x1 = draw_area.x1;
455	        txt_area.y1 = draw_area.y1;
456	        txt_area.x2 = draw_area.x1 + txt_size.x - 1;
457	        txt_area.y2 = draw_area.y1 + txt_size.y - 1;
458	
459	        lv_draw_rect_dsc_init(&rect_dsc);
460	        rect_dsc.bg_color = lv_color_white();
461	        lv_draw_epic_fill(t, &rect_dsc, &txt_area);
462	
463	        char buf[8];
464	        lv_snprintf(buf, sizeof(buf), "%d", idx);
465	        lv_draw_label_dsc_t label_dsc;
466	        lv_draw_label_dsc_init(&label_dsc);
467	        label_dsc.color = lv_color_black();
468	        label_dsc.text = buf;
469	        lv_draw_epic_label(t, &label_dsc, &txt_area);
470	    }
471	#endif
472	}
