485	static void render_thread_cb(void *ptr)
486	{
487	    lv_draw_epic_unit_t *u = ptr;
488	
489	    lv_thread_sync_init(&u->sync);
490	    u->inited = true;
491	
492	    while (1)
493	    {
494	        /* Wait for sync if there is no task set. */
495	        while (u->task_act == NULL)
496	        {
497	            if (u->exit_status)
498	                break;
499	
500	            lv_thread_sync_wait(&u->sync);
501	        }
502	
503	        if (u->exit_status)
504	        {
505	            LV_LOG_INFO("Ready to exit EPIC draw thread.");
506	            break;
507	        }
508	
509	        execute_drawing(u);
510	
511	        /* Signal the ready state to dispatcher. */
512	        u->task_act->state = LV_DRAW_TASK_STATE_FINISHED;
513	
514	        /* Cleanup. */
515	        u->task_act = NULL;
516	
517	        /* The draw unit is free now. Request a new dispatching as it can get a new task. */
518	        lv_draw_dispatch_request();
519	    }
520	
521	    u->inited = false;
522	    lv_thread_sync_delete(&u->sync);
523	    LV_LOG_INFO("Exit EPIC draw thread.");
524	}
525	#endif
