46	uint32_t lv_img_2_epic_cf(lv_color_format_t cf)
47	{
48	    uint32_t color_mode;
49	
50	    switch (cf)
51	    {
52	    /*2 byte (+alpha) formats*/
53	    case LV_COLOR_FORMAT_RGB565:
54	        color_mode = EPIC_INPUT_RGB565;
55	        break;
56	#ifdef EPIC_SUPPORT_MASK
57	    case LV_COLOR_FORMAT_RGB565A8:
58	        color_mode = EPIC_INPUT_RGB565;
59	        break;
60	#endif /*EPIC_SUPPORT_MASK*/
61	
62	    /*3 byte (+alpha) formats*/
63	    case LV_COLOR_FORMAT_RGB888:
64	        color_mode = EPIC_INPUT_RGB888;
65	        break;
66	    case LV_COLOR_FORMAT_ARGB8888:
67	    case LV_COLOR_FORMAT_XRGB8888:
68	        color_mode = EPIC_INPUT_ARGB8888;
69	        break;
70	    case LV_COLOR_FORMAT_ARGB8565:
71	        color_mode = EPIC_INPUT_ARGB8565;
72	        break;
73	
74	#ifdef EPIC_SUPPORT_A8
75	    case LV_COLOR_FORMAT_A8:
76	        color_mode = EPIC_INPUT_A8;
77	        break;
78	#endif /*EPIC_SUPPORT_A8*/
79	
80	#ifdef EPIC_SUPPORT_A4
81	    case LV_COLOR_FORMAT_A4:
82	        color_mode = EPIC_INPUT_A4;
83	        break;
84	#endif /*EPIC_SUPPORT_A4*/
85	
86	#ifdef EPIC_SUPPORT_A2
87	    case LV_COLOR_FORMAT_A2:
88	        color_mode = EPIC_INPUT_A2;
89	        break;
90	#endif /*EPIC_SUPPORT_A2*/
91	
92	#ifdef EPIC_SUPPORT_L8
93	    case LV_COLOR_FORMAT_I8:
