96	        break;
97	#endif /*EPIC_SUPPORT_L8*/
98	
99	#ifdef EPIC_SUPPORT_YUV
100	    case LV_COLOR_FORMAT_I420:
101	        color_mode = EPIC_INPUT_YUV420_PLANAR;
102	        break;
103	    case LV_COLOR_FORMAT_YUY2:
104	        color_mode = EPIC_INPUT_YUV422_PACKED_YUYV;
105	        break;
