130	uint32_t lv_epic_setup_bg_and_output_layer(EPIC_LayerConfigTypeDef *epic_bg_layer,
131	        EPIC_LayerConfigTypeDef *epic_output_layer,
132	        lv_draw_task_t *draw_task, const lv_area_t *coords)
133	{
134	    lv_layer_t *layer = draw_task->target_layer;
135	
136	    lv_area_t blend_area;
137	    if (!lv_area_intersect(&blend_area, coords, &draw_task->clip_area))
138	        return 1; /*Fully clipped, nothing to do*/
139	
140	    lv_color_format_t dest_cf = layer->color_format;
141	
142	    /*Setup bg layer*/
143	    HAL_EPIC_LayerConfigInit(epic_bg_layer);
144	    epic_bg_layer->color_en = false;
145	    epic_bg_layer->data = (uint8_t *)lv_draw_layer_go_to_xy(layer, 0, 0);
146	    epic_bg_layer->color_mode = lv_img_2_epic_cf(dest_cf);
147	    epic_bg_layer->width = lv_area_get_width(&layer->buf_area);
148	    epic_bg_layer->total_width = lv_area_get_width(&layer->buf_area);
149	    epic_bg_layer->height = lv_area_get_height(&layer->buf_area);
150	    epic_bg_layer->x_offset = layer->buf_area.x1;
151	    epic_bg_layer->y_offset = layer->buf_area.y1;
152	
153	
154	    /*Setup output layer*/
155	    memcpy(epic_output_layer, epic_bg_layer, sizeof(EPIC_LayerConfigTypeDef));
156	    epic_output_layer->width = lv_area_get_width(&blend_area);
157	    epic_output_layer->height = lv_area_get_height(&blend_area);
158	    epic_output_layer->x_offset = blend_area.x1;
159	    epic_output_layer->y_offset = blend_area.y1;
160	
161	    epic_output_layer->data = (uint8_t *)lv_draw_layer_go_to_xy(layer,
162	                              blend_area.x1 - layer->buf_area.x1,
163	                              blend_area.y1 - layer->buf_area.y1);
164	
165	
166	    LV_ASSERT((epic_output_layer->height * epic_output_layer->width) <= GPU_OPERATION_MAX_PIXELS);
167	
168	    return 0;
169	}
