172	void lv_epic_draw_blend(lv_draw_task_t *draw_task, const lv_draw_sw_blend_dsc_t *blend_dsc)
173	{
174	    /*Do not draw transparent things*/
175	    if (blend_dsc->opa <= LV_OPA_MIN) return;
176	    if (blend_dsc->mask_buf && blend_dsc->mask_res == LV_DRAW_SW_MASK_RES_TRANSP) return;
177	
178	    lv_area_t blend_area;
179	    if (!lv_area_intersect(&blend_area, blend_dsc->blend_area, &draw_task->clip_area)) return;
180	
181	
182	    EPIC_LayerConfigTypeDef input_layers[3];
183	    EPIC_LayerConfigTypeDef output_canvas;
184	
185	    int ret;
186	
187	
188	    if (lv_epic_setup_bg_and_output_layer(&input_layers[0], &output_canvas, draw_task, blend_dsc->blend_area))
189	        return;/*Fully clipped, nothing to do*/
190	
191	
192	
193	    if (blend_dsc->src_buf == NULL)
194	    {
195	        output_canvas.color_r = blend_dsc->color.red;
196	        output_canvas.color_g = blend_dsc->color.green;
197	        output_canvas.color_b = blend_dsc->color.blue;
198	
199	        LV_ASSERT((output_canvas.height * output_canvas.width) <= GPU_OPERATION_MAX_PIXELS);
200	        output_canvas.color_en = true;
201	
202	
203	        if ((blend_dsc->mask_buf) && (blend_dsc->mask_res != LV_DRAW_SW_MASK_RES_FULL_COVER))
204	        {
205	#if defined(EPIC_SUPPORT_MONOCHROME_LAYER)&&defined(EPIC_SUPPORT_MASK)
206	
207	            HAL_EPIC_LayerConfigInit(&input_layers[1]);
208	            input_layers[1].data = (uint8_t *)blend_dsc->mask_buf;
209	            input_layers[1].x_offset = blend_dsc->mask_area->x1;
210	            input_layers[1].y_offset = blend_dsc->mask_area->y1;
211	            input_layers[1].width = lv_area_get_width(blend_dsc->mask_area);
212	            input_layers[1].total_width = lv_area_get_width(blend_dsc->mask_area);
213	            input_layers[1].height = lv_area_get_height(blend_dsc->mask_area);
214	            input_layers[1].color_mode = EPIC_INPUT_A8;
215	            input_layers[1].ax_mode = ALPHA_BLEND_RGBCOLOR;
216	            input_layers[1].color_r = blend_dsc->color.red;
217	            input_layers[1].color_g = blend_dsc->color.green;
218	            input_layers[1].color_b = blend_dsc->color.blue;
219	            input_layers[1].alpha = blend_dsc->opa;
220	            input_layers[1].color_en = true;
221	
222	
223	            output_canvas.color_en = false;
224	
225	            ret = drv_epic_fill_ext(input_layers, 2, &output_canvas, NULL);
226	#else
227	            LV_ASSERT(0);
228	#endif /* EPIC_SUPPORT_MONOCHROME_LAYER&&EPIC_SUPPORT_MASK */
229	        }
230	        else if (blend_dsc->opa < LV_OPA_MAX)
231	        {
232	            input_layers[0].alpha = (0 == blend_dsc->opa) ? 255 : (256 - blend_dsc->opa);
233	
234	            ret = drv_epic_fill_ext(input_layers, 1, &output_canvas, NULL);
235	        }
236	        else
237	        {
238	            ret = drv_epic_fill_ext(NULL, 0, &output_canvas, NULL);
239	        }
240	
241	        LV_ASSERT(0 == ret);
242	
243	    }
244	    else
245	    {
246	        if (!lv_area_intersect(&blend_area, &blend_area, blend_dsc->src_area)) return;
247	
248	        /*Setup fg layer*/
249	        HAL_EPIC_LayerConfigInit(&input_layers[1]);
250	
251	        input_layers[1].alpha = blend_dsc->opa;
252	        input_layers[1].x_offset = blend_dsc->src_area->x1;
253	        input_layers[1].y_offset = blend_dsc->src_area->y1;
254	
255	        input_layers[1].color_mode = lv_img_2_epic_cf(blend_dsc->src_color_format);
256	        input_layers[1].data = (uint8_t *)blend_dsc->src_buf;
257	        input_layers[1].width = lv_area_get_width(blend_dsc->src_area);
258	        input_layers[1].height = lv_area_get_height(blend_dsc->src_area);
259	        input_layers[1].total_width = blend_dsc->src_stride / lv_color_format_get_size(blend_dsc->src_color_format);
260	
261	
262	        if ((blend_dsc->mask_buf) && (blend_dsc->mask_res != LV_DRAW_SW_MASK_RES_FULL_COVER))
263	        {
264	#if defined(EPIC_SUPPORT_MONOCHROME_LAYER)&&defined(EPIC_SUPPORT_MASK)
265	
266	            HAL_EPIC_LayerConfigInit(&input_layers[2]);
267	            input_layers[2].data = (uint8_t *)blend_dsc->mask_buf;
268	            input_layers[2].x_offset = blend_dsc->mask_area->x1;
269	            input_layers[2].y_offset = blend_dsc->mask_area->y1;
270	            input_layers[2].width = lv_area_get_width(blend_dsc->mask_area);
271	            input_layers[2].total_width = lv_area_get_width(blend_dsc->mask_area);
272	            input_layers[2].height = lv_area_get_height(blend_dsc->mask_area);
273	            input_layers[2].color_mode = EPIC_INPUT_A8;
274	            input_layers[2].ax_mode = ALPHA_BLEND_MASK;
275	
276	
277	            ret = drv_epic_blend(input_layers, 3, &output_canvas, NULL);
278	#else
279	            LV_ASSERT(0);
280	#endif /* EPIC_SUPPORT_MONOCHROME_LAYER&&EPIC_SUPPORT_MASK */
281	        }
282	        else
283	        {
284	            ret = drv_epic_blend(input_layers, 2, &output_canvas, NULL);
285	        }
286	
287	        LV_ASSERT(0 == ret);
288	    }
289	}
