50	void lv_draw_epic_fill(lv_draw_task_t *draw_task, const lv_draw_fill_dsc_t *dsc,
51	                       const lv_area_t *coords)
52	{
53	    if (dsc->opa <= (lv_opa_t)LV_OPA_MIN)
54	        return;
55	
56	    lv_layer_t *layer = draw_task->target_layer;
57	
58	    lv_area_t blend_area;
59	    if (!lv_area_intersect(&blend_area, coords, &draw_task->clip_area))
60	        return; /*Fully clipped, nothing to do*/
61	
62	    if (!lv_area_intersect(&blend_area, &blend_area, &layer->buf_area))
63	        return; /*Fully clipped, nothing to do*/
64	
65	
66	    lv_color_format_t dest_cf = layer->color_format;
67	    uint8_t *dest_blend_area_buf = lv_draw_layer_go_to_xy(layer, blend_area.x1 - layer->buf_area.x1,
68	                                   blend_area.y1 - layer->buf_area.y1);
69	
70	    /*Call epic**/
71	    lv_grad_dir_t grad_dir = (lv_grad_dir_t) dsc->grad.dir;
72	
73	    if (LV_GRAD_DIR_NONE == grad_dir)
74	    {
75	        EPIC_LayerConfigTypeDef input_layers[1];
76	        EPIC_LayerConfigTypeDef output_canvas;
77	
78	        int ret;
79	        if (lv_epic_setup_bg_and_output_layer(&input_layers[0], &output_canvas, draw_task, coords))
80	            return;/*Fully clipped, nothing to do*/
81	
82	        output_canvas.color_r = dsc->color.red;
83	        output_canvas.color_g = dsc->color.green;
84	        output_canvas.color_b = dsc->color.blue;
85	        output_canvas.color_en = true;
86	
87	        if (dsc->opa < LV_OPA_MAX)
88	        {
89	            input_layers[0].alpha = (0 == dsc->opa) ? 255 : (256 - dsc->opa);
90	
91	            ret = drv_epic_fill_ext(input_layers, 1, &output_canvas, NULL);
92	        }
93	        else
94	        {
95	            ret = drv_epic_fill_ext(NULL, 0, &output_canvas, NULL);
96	        }
97	        LV_ASSERT(0 == ret);
98	    }
99	    else
100	    {
101	        uint32_t epic_cf = lv_img_2_epic_cf(dest_cf);
102	        
103	        LV_ASSERT_MSG(EPIC_SUPPROT_OUT_FORMAT(epic_cf), "EPIC: Color format not supported for gradient fill");
104	        
105	        EPIC_GradCfgTypeDef param;
106	        HAL_EPIC_FillGradDataInit(&param);
107	
108	        param.start = dest_blend_area_buf;
109	        param.color_mode = epic_cf;
110	        param.width = lv_area_get_width(&blend_area);
111	        param.height = lv_area_get_height(&blend_area);
112	        param.total_width = lv_area_get_width(&layer->buf_area);
113	
114	        if (LV_GRAD_DIR_VER == grad_dir)
115	        {
116	            LV_ASSERT(2 == dsc->grad.stops_count);
117	            EPIC_ColorDef epic_color1 = lv_color_to_epic_color(dsc->grad.stops[0].color, LV_OPA_MIX2(dsc->grad.stops[0].opa, dsc->opa));
118	            EPIC_ColorDef epic_color2 = lv_color_to_epic_color(dsc->grad.stops[1].color, LV_OPA_MIX2(dsc->grad.stops[1].opa, dsc->opa));
119	
120	            param.color[0][0] = epic_color1;
121	            param.color[0][1] = epic_color1;
122	            param.color[1][0] = epic_color2;
123	            param.color[1][1] = epic_color2;
124	        }
125	        else if (LV_GRAD_DIR_HOR == grad_dir)
126	        {
127	            LV_ASSERT(2 == dsc->grad.stops_count);
128	            EPIC_ColorDef epic_color1 = lv_color_to_epic_color(dsc->grad.stops[0].color, LV_OPA_MIX2(dsc->grad.stops[0].opa, dsc->opa));
129	            EPIC_ColorDef epic_color2 = lv_color_to_epic_color(dsc->grad.stops[1].color, LV_OPA_MIX2(dsc->grad.stops[1].opa, dsc->opa));
130	
131	            param.color[0][0] = epic_color1;
132	            param.color[0][1] = epic_color2;
133	            param.color[1][0] = epic_color1;
134	            param.color[1][1] = epic_color2;
135	        }
136	        else
137	        {
138	            EPIC_ColorDef epic_color = lv_color_to_epic_color(dsc->color, dsc->opa);
139	
140	            param.color[0][0] = epic_color;
141	            param.color[0][1] = epic_color;
142	            param.color[1][0] = epic_color;
143	            param.color[1][1] = epic_color;
144	        }
145	
146	
147	
148	        int ret_v = drv_epic_fill_grad(&param, NULL);
