63	void lv_draw_epic_layer(lv_draw_task_t *draw_task, const lv_draw_image_dsc_t *draw_dsc, const lv_area_t *coords)
64	{
65	    lv_layer_t *layer_to_draw = (lv_layer_t *)draw_dsc->src;
66	
67	    /*It can happen that nothing was draw on a layer and therefore its buffer is not allocated.
68	     *In this case just return. */
69	    if (layer_to_draw->draw_buf == NULL) return;
70	
71	    lv_draw_image_dsc_t new_draw_dsc = *draw_dsc;
72	    new_draw_dsc.src = layer_to_draw->draw_buf;
73	    lv_draw_epic_img(draw_task, &new_draw_dsc, coords);
74	#if LV_USE_LAYER_DEBUG || LV_USE_PARALLEL_DRAW_DEBUG
75	    lv_area_t area_rot;
76	    lv_area_copy(&area_rot, coords);
77	    if (draw_dsc->rotation || draw_dsc->scale_x != LV_SCALE_NONE || draw_dsc->scale_y != LV_SCALE_NONE)
78	    {
79	        int32_t w = lv_area_get_width(coords);
80	        int32_t h = lv_area_get_height(coords);
81	
82	        _lv_image_buf_get_transformed_area(&area_rot, w, h, draw_dsc->rotation, draw_dsc->scale_x, draw_dsc->scale_y,
83	                                           &draw_dsc->pivot);
84	
85	        area_rot.x1 += coords->x1;
86	        area_rot.y1 += coords->y1;
87	        area_rot.x2 += coords->x1;
88	        area_rot.y2 += coords->y1;
89	    }
90	    lv_area_t draw_area;
91	    if (!lv_area_intersect(&draw_area, &area_rot, &draw_task->clip_area)) return;
92	#endif
93	
94	#if LV_USE_LAYER_DEBUG
95	    lv_draw_fill_dsc_t fill_dsc;
96	    lv_draw_fill_dsc_init(&fill_dsc);
97	    fill_dsc.color = lv_color_hex(layer_to_draw->color_format == LV_COLOR_FORMAT_ARGB8888 ? 0xff0000 : 0x00ff00);
98	    fill_dsc.opa = LV_OPA_20;
99	    lv_draw_sw_fill(draw_task, &fill_dsc, &area_rot);
100	
101	    lv_draw_border_dsc_t border_dsc;
102	    lv_draw_border_dsc_init(&border_dsc);
103	    border_dsc.color = fill_dsc.color;
104	    border_dsc.opa = LV_OPA_60;
105	    border_dsc.width = 2;
106	    lv_draw_sw_border(draw_task, &border_dsc, &area_rot);
107	
108	#endif
109	
110	#if LV_USE_PARALLEL_DRAW_DEBUG
111	    uint32_t idx = 0;
112	    lv_draw_task_t *draw_task_tmp = _draw_info.unit_head;
113	    while (draw_task_tmp != draw_task)
114	    {
115	        draw_task_tmp = draw_task_tmp->next;
116	        idx++;
117	    }
118	
119	    lv_draw_fill_dsc_t fill_dsc;
120	    lv_draw_rect_dsc_init(&fill_dsc);
121	    fill_dsc.color = lv_palette_main(idx % _LV_PALETTE_LAST);
122	    fill_dsc.opa = LV_OPA_10;
123	    lv_draw_sw_fill(draw_task, &fill_dsc, &area_rot);
124	
125	    lv_draw_border_dsc_t border_dsc;
126	    lv_draw_border_dsc_init(&border_dsc);
127	    border_dsc.color = lv_palette_main(idx % _LV_PALETTE_LAST);
128	    border_dsc.opa = LV_OPA_100;
129	    border_dsc.width = 2;
130	    lv_draw_sw_border(draw_task, &border_dsc, &area_rot);
131	
132	    lv_point_t txt_size;
133	    lv_text_get_size(&txt_size, "W", LV_FONT_DEFAULT, 0, 0, 100, LV_TEXT_FLAG_NONE);
134	
135	    lv_area_t txt_area;
136	    txt_area.x1 = draw_area.x1;
137	    txt_area.x2 = draw_area.x1 + txt_size.x - 1;
138	    txt_area.y2 = draw_area.y2;
139	    txt_area.y1 = draw_area.y2 - txt_size.y + 1;
140	
141	    lv_draw_fill_dsc_init(&fill_dsc);
142	    fill_dsc.color = lv_color_black();
143	    lv_draw_sw_fill(draw_task, &fill_dsc, &txt_area);
144	
145	    char buf[8];
146	    lv_snprintf(buf, sizeof(buf), "%d", idx);
147	    lv_draw_label_dsc_t label_dsc;
148	    lv_draw_label_dsc_init(&label_dsc);
149	    label_dsc.color = lv_color_white();
150	    label_dsc.text = buf;
151	    lv_draw_sw_label(draw_task, &label_dsc, &txt_area);
152	#endif
153	}
