170	
171	static void img_draw_core(lv_draw_task_t *draw_task, const lv_draw_image_dsc_t *draw_dsc,
172	                          const lv_image_decoder_dsc_t *decoder_dsc, lv_draw_image_sup_t *sup,
173	                          const lv_area_t *img_coords, const lv_area_t *clipped_img_area)
174	{
175	    const lv_draw_buf_t *decoded = decoder_dsc->decoded;
176	    const uint8_t *src_buf = decoded->data;
177	    //const lv_image_header_t * header = &decoded->header;
178	    lv_color_format_t cf = decoded->header.cf;
179	    uint32_t img_total_width;
180	
181	    if (decoded->header.flags & (LV_IMAGE_FLAGS_EZIP | LV_IMAGE_FLAGS_JPEG))
182	        img_total_width = decoded->header.w;
183	    else
184	        img_total_width = decoded->header.stride / lv_color_format_get_size(cf);
185	
186	    /*The whole image is available, just draw it*/
187	    if (src_buf)
188	    {
189	        EPIC_LayerConfigTypeDef input_layers[3];
190	        EPIC_LayerConfigTypeDef output_canvas;
191	
192	        uint8_t input_layer_cnt = 2;
193	
194	        if (lv_epic_setup_bg_and_output_layer(&input_layers[0], &output_canvas, draw_task, clipped_img_area))
195	            return; /*Fully clipped, nothing to do*/
196	
197	
198	        /*Setup fg layer*/
199	        HAL_EPIC_LayerConfigInit(&input_layers[1]);
200	
201	        input_layers[1].transform_cfg.angle   = (draw_dsc->rotation + 3600) % 3600;
202	        input_layers[1].transform_cfg.pivot_x = draw_dsc->pivot.x;
203	        input_layers[1].transform_cfg.pivot_y = draw_dsc->pivot.y;
204	        input_layers[1].transform_cfg.scale_x = LV_SCALE_NONE * EPIC_INPUT_SCALE_NONE / (uint32_t)draw_dsc->scale_x;
205	        input_layers[1].transform_cfg.scale_y = LV_SCALE_NONE * EPIC_INPUT_SCALE_NONE / (uint32_t)draw_dsc->scale_y;
206	
207	        input_layers[1].alpha = draw_dsc->opa;
208	        input_layers[1].x_offset = img_coords->x1;
209	        input_layers[1].y_offset = img_coords->y1;
210	
211	        if (decoded->header.flags & LV_IMAGE_FLAGS_EZIP)
212	            input_layers[1].color_mode = EPIC_INPUT_EZIP;
213	        else if (decoded->header.flags & LV_IMAGE_FLAGS_JPEG)
214	            input_layers[1].color_mode = EPIC_INPUT_JPEG;
215	        else
216	            input_layers[1].color_mode = lv_img_2_epic_cf(cf);
217	
218	        input_layers[1].data = (uint8_t *)src_buf;
219	        input_layers[1].data_size = decoded->data_size;
220	
221	        input_layers[1].width = lv_area_get_width(img_coords);
222	        input_layers[1].height = lv_area_get_height(img_coords);
223	        input_layers[1].total_width = img_total_width;
224	
225	        if (EPIC_INPUT_A8 == input_layers[1].color_mode)
226	        {
227	            input_layers[1].color_en = true;
228	            input_layers[1].color_r = draw_dsc->recolor.red;
229	            input_layers[1].color_g = draw_dsc->recolor.green;
230	            input_layers[1].color_b = draw_dsc->recolor.blue;
231	        }
232	        else if (EPIC_INPUT_L8 == input_layers[1].color_mode)
233	        {
234	            input_layers[1].lookup_table = (uint8_t *)decoder_dsc->palette;
235	        }
236	        else
237	        {
238	            input_layers[1].color_en = false;
239	        }
240	
241	        if (LV_COLOR_FORMAT_RGB565A8 == cf)
242	        {
243	
244	            /*Setup alpha layer*/
245	            HAL_EPIC_LayerConfigInit(&input_layers[input_layer_cnt]);
246	
247	            input_layers[input_layer_cnt].alpha = draw_dsc->opa;
248	            input_layers[input_layer_cnt].x_offset = img_coords->x1;
249	            input_layers[input_layer_cnt].y_offset = img_coords->y1;
250	            input_layers[input_layer_cnt].color_mode = EPIC_INPUT_A8;
251	            input_layers[input_layer_cnt].data = ((uint8_t *)src_buf) + lv_area_get_size(img_coords) * 2;
252	            input_layers[input_layer_cnt].ax_mode = ALPHA_BLEND_OVERWRITE;
253	            input_layers[input_layer_cnt].width = lv_area_get_width(img_coords);
254	            input_layers[input_layer_cnt].height = lv_area_get_height(img_coords);
255	            input_layers[input_layer_cnt].total_width = img_total_width;
256	            input_layer_cnt++;
257	        }
258	
259	        lv_image_decoder_dsc_t mask_decoder_dsc;
260	        lv_result_t decoder_res = LV_RESULT_INVALID;
261	
262	        if (draw_dsc->bitmap_mask_src != NULL)
263	        {
264	            lv_area_t mask_area;
265	            const lv_image_dsc_t *mask_dsc = draw_dsc->bitmap_mask_src;
266	            lv_image_src_t mask_src_type = lv_image_src_get_type(mask_dsc);
267	            // Determine whether it is a variable type and in A8 format.
268	            if (lv_image_src_get_type(mask_dsc) == LV_IMAGE_SRC_VARIABLE && mask_dsc->header.cf == LV_COLOR_FORMAT_A8)
269	            {
270	
271	
272	                const lv_image_header_t *header = &mask_dsc->header;
273	
274	                const lv_area_t *image_area;
275	                if (lv_area_get_width(&draw_dsc->image_area) < 0) image_area = img_coords;
276	                else image_area = &draw_dsc->image_area;
277	
278	                lv_area_set(&mask_area, 0, 0, header->w - 1, header->h - 1);
279	                lv_area_align(image_area, &mask_area, LV_ALIGN_CENTER, 0, 0);
280	
281	                HAL_EPIC_LayerConfigInit(&input_layers[input_layer_cnt]);
282	
283	                input_layers[input_layer_cnt].alpha = 255;
284	                input_layers[input_layer_cnt].x_offset = mask_area.x1;
285	                input_layers[input_layer_cnt].y_offset = mask_area.y1;
286	                input_layers[input_layer_cnt].color_mode = EPIC_INPUT_A8;
287	                input_layers[input_layer_cnt].data = (uint8_t *)mask_dsc->data;
288	                input_layers[input_layer_cnt].ax_mode = ALPHA_BLEND_OVERWRITE;
289	                input_layers[input_layer_cnt].width = lv_area_get_width(&mask_area);
290	                input_layers[input_layer_cnt].height = lv_area_get_height(&mask_area);
291	                input_layers[input_layer_cnt].total_width = header->stride;
292	
293	
294	                input_layer_cnt++;
295	            }
296	            else
297	            {
298	
299	                decoder_res = lv_image_decoder_open(&mask_decoder_dsc, draw_dsc->bitmap_mask_src, NULL);
300	                if (decoder_res == LV_RESULT_OK && mask_decoder_dsc.decoded)
301	                {
302	                    const lv_draw_buf_t *mask_img = mask_decoder_dsc.decoded;
303	
304	                    if (mask_img->header.cf == LV_COLOR_FORMAT_A8 ||
305	                            mask_img->header.cf == LV_COLOR_FORMAT_L8)
306	                    {
307	                        const lv_area_t *image_area;
308	                        if (lv_area_get_width(&draw_dsc->image_area) < 0) image_area = img_coords;
309	                        else image_area = &draw_dsc->image_area;
310	
311	                        lv_area_set(&mask_area, 0, 0, mask_img->header.w - 1, mask_img->header.h - 1);
312	                        lv_area_align(image_area, &mask_area, LV_ALIGN_CENTER, 0, 0);
313	
314	                        // Setup mask layer
315	                        HAL_EPIC_LayerConfigInit(&input_layers[input_layer_cnt]);
316	
317	                        input_layers[input_layer_cnt].alpha = 255;
318	                        input_layers[input_layer_cnt].x_offset = mask_area.x1;
319	                        input_layers[input_layer_cnt].y_offset = mask_area.y1;
320	                        input_layers[input_layer_cnt].color_mode = EPIC_INPUT_A8;
321	                        input_layers[input_layer_cnt].data = (uint8_t *)mask_img->data;
322	                        input_layers[input_layer_cnt].ax_mode = ALPHA_BLEND_OVERWRITE;
323	                        input_layers[input_layer_cnt].width = lv_area_get_width(&mask_area);
324	                        input_layers[input_layer_cnt].height = lv_area_get_height(&mask_area);
325	                        input_layers[input_layer_cnt].total_width = mask_img->header.stride;
326	
327	                        input_layer_cnt++;
328	                    }
329	                    else
330	                    {
331	                        LV_LOG_WARN("The mask image is not A8/L8 format. Drawing the image without mask.\n");
332	                    }
333	
334	                    lv_image_decoder_close(&mask_decoder_dsc);
335	                }
336	                else
337	                {
338	                    LV_LOG_WARN("Couldn't decode the mask image. Drawing the image without mask.\n");
339	                }
340	            }
341	        }
342	
343	        int ret = drv_epic_blend(input_layers, input_layer_cnt, &output_canvas, NULL);
344	        LV_ASSERT(0 == ret);
345	
346	        if (decoder_res == LV_RESULT_OK)
347	        {
348	            lv_image_decoder_close(&mask_decoder_dsc);
349	        }
350	    }
351	}
