61	void print_letter_map(uint32_t letter, const uint8_t *map_p, uint16_t box_w, uint16_t box_h, uint32_t bpp)
62	{
63	
64	    uint32_t bitmask_init;
65	    uint32_t bitmask;
66	    int32_t col, row;
67	    uint32_t col_bit_max = 8 - bpp;
68	    uint32_t col_bit_row_ofs = 0;
69	
70	    uint32_t col_bit = 0;
71	
72	    switch (bpp)
73	    {
74	    case 1:
75	        bitmask_init  = 0x01;
76	        break;
77	    case 2:
78	        bitmask_init  = 0x03;
79	        break;
80	    case 4:
81	        bitmask_init  = 0x0F;
82	        break;
83	    case 8:
84	        bitmask_init  = 0xFF;
85	        break;       /*No opa table, pixel value will be used directly*/
86	    default:
87	        LV_LOG_WARN("lv_draw_letter: invalid bpp");
88	        return; /*Invalid bpp. Can't render the letter*/
89	    }
90	
91	
92	    rt_kprintf("print_letter_map[%c], bpp=%d, wh=%d,%d map=%x \r\n", letter, bpp, box_w, box_h, map_p);
93	
94	    box_w = ((box_w + (8 / bpp) - 1) / (8 / bpp)) * (8 / bpp); //Align to 1 byte
95	
96	    for (row = 0 ; row < box_h; row++)
97	    {
98	
99	        const uint8_t *col_map_p = map_p;
100	        bitmask = bitmask_init << col_bit;
101	        for (col = 0; col < box_w; col++)
102	        {
103	            /*Load the pixel's opacity into the mask*/
104	            uint8_t letter_px = (*map_p & bitmask) >> col_bit;
105	
106	            if (letter_px)
107	                if (8 == bpp)
108	                    rt_kprintf("%x", letter_px >> 4);
109	                else
110	                    rt_kprintf("%x", letter_px);
111	            else
112	                rt_kprintf(".");
113	
114	
115	
116	            /*Go to the next column*/
117	            if (col_bit < col_bit_max)
118	            {
119	                col_bit += bpp;
120	                bitmask = bitmask << bpp;
121	            }
122	            else
123	            {
124	                col_bit = 0;
125	                bitmask = bitmask_init;
126	                map_p++;
127	            }
128	        }
129	
130	
131	        rt_kprintf("(0x%x:", col_map_p);
132	        do
133	        {
134	            rt_kprintf("%02x,", *col_map_p);
135	            col_map_p++;
136	        }
137	        while (col_map_p < map_p);
138	        rt_kprintf(")");
139	
140	
141	        rt_kprintf("\r\n");
142	        col_bit += col_bit_row_ofs;
143	        map_p += (col_bit >> 3);
144	        col_bit = col_bit & 0x7;
145	    }
146	
147	}
