67	void lv_draw_epic_border(lv_draw_task_t *draw_task, const lv_draw_border_dsc_t *dsc, const lv_area_t *coords)
68	{
69	    if (dsc->opa <= LV_OPA_MIN) return;
70	    if (dsc->width == 0) return;
71	    if (dsc->side == LV_BORDER_SIDE_NONE) return;
72	
73	    int32_t coords_w = lv_area_get_width(coords);
74	    int32_t coords_h = lv_area_get_height(coords);
75	    int32_t rout = dsc->radius;
76	    int32_t short_side = LV_MIN(coords_w, coords_h);
77	    if (rout > short_side >> 1) rout = short_side >> 1;
78	
79	    /*Get the inner area*/
80	    lv_area_t area_inner;
81	    lv_area_copy(&area_inner, coords);
82	    area_inner.x1 += ((dsc->side & LV_BORDER_SIDE_LEFT) ? dsc->width : - (dsc->width + rout));
83	    area_inner.x2 -= ((dsc->side & LV_BORDER_SIDE_RIGHT) ? dsc->width : - (dsc->width + rout));
84	    area_inner.y1 += ((dsc->side & LV_BORDER_SIDE_TOP) ? dsc->width : - (dsc->width + rout));
85	    area_inner.y2 -= ((dsc->side & LV_BORDER_SIDE_BOTTOM) ? dsc->width : - (dsc->width + rout));
86	
87	    lv_coord_t rin = rout - dsc->width;
88	    if (rin < 0) rin = 0;
89	
90	    if (rout == 0 && rin == 0)
91	    {
92	        draw_border_simple(draw_task, coords, &area_inner, dsc->color, dsc->opa);
93	    }
94	    else
95	    {
96	        draw_border_complex(draw_task, coords, &area_inner, rout, rin, dsc->color, dsc->opa);
97	    }
98	
99	}
