105	void draw_border_complex(lv_draw_task_t *draw_task, const lv_area_t *outer_area, const lv_area_t *inner_area,
106	                         lv_coord_t rout, lv_coord_t rin, lv_color_t color, lv_opa_t opa)
107	{
108	#if LV_DRAW_SW_COMPLEX
109	    /*Get clipped draw area which is the real draw area.
110	     *It is always the same or inside `coords`*/
111	    lv_area_t draw_area;
112	    if (!lv_area_intersect(&draw_area, outer_area, &draw_task->clip_area)) return;
113	    int32_t draw_area_w = lv_area_get_width(&draw_area);
114	
115	    lv_draw_sw_blend_dsc_t blend_dsc;
116	    lv_memzero(&blend_dsc, sizeof(blend_dsc));
117	    lv_opa_t *mask_buf = lv_malloc(draw_area_w);
118	    blend_dsc.mask_buf = mask_buf;
119	
120	
121	    void *mask_list[3] = {0};
122	
123	    /*Create mask for the inner mask*/
124	    lv_draw_sw_mask_radius_param_t mask_rin_param;
125	    lv_draw_sw_mask_radius_init(&mask_rin_param, inner_area, rin, true);
126	    mask_list[0] = &mask_rin_param;
127	
128	
129	    /*Create mask for the outer area*/
130	    lv_draw_sw_mask_radius_param_t mask_rout_param;
131	    if (rout > 0)
132	    {
133	        lv_draw_sw_mask_radius_init(&mask_rout_param, outer_area, rout, false);
134	        mask_list[1] = &mask_rout_param;
135	    }
136	
137	    int32_t h;
138	    lv_area_t blend_area;
139	    blend_dsc.blend_area = &blend_area;
140	    blend_dsc.mask_area = &blend_area;
141	    blend_dsc.color = color;
142	    blend_dsc.opa = opa;
143	
144	    /*Calculate the x and y coordinates where the straight parts area is*/
145	    lv_area_t core_area;
146	    core_area.x1 = LV_MAX(outer_area->x1 + rout, inner_area->x1);
147	    core_area.x2 = LV_MIN(outer_area->x2 - rout, inner_area->x2);
148	    core_area.y1 = LV_MAX(outer_area->y1 + rout, inner_area->y1);
149	    core_area.y2 = LV_MIN(outer_area->y2 - rout, inner_area->y2);
150	    lv_coord_t core_w = lv_area_get_width(&core_area);
151	
152	    bool top_side = outer_area->y1 <= inner_area->y1;
153	    bool bottom_side = outer_area->y2 >= inner_area->y2;
154	
155	    /*No masks*/
156	    bool left_side = outer_area->x1 <= inner_area->x1;
157	    bool right_side = outer_area->x2 >= inner_area->x2;
158	
159	    bool split_hor = true;
160	    if (left_side && right_side && top_side && bottom_side &&
161	            core_w < SPLIT_LIMIT)
162	    {
163	        split_hor = false;
164	    }
165	
166	
167	    blend_dsc.mask_res = LV_DRAW_SW_MASK_RES_FULL_COVER;
168	    /*Draw the straight lines first if they are long enough*/
169	    if (top_side && split_hor)
170	    {
171	        blend_area.x1 = core_area.x1;
172	        blend_area.x2 = core_area.x2;
173	        blend_area.y1 = outer_area->y1;
174	        blend_area.y2 = inner_area->y1 - 1;
175	        lv_epic_draw_blend(draw_task, &blend_dsc);
176	    }
177	
178	    if (bottom_side && split_hor)
179	    {
180	        blend_area.x1 = core_area.x1;
181	        blend_area.x2 = core_area.x2;
182	        blend_area.y1 = inner_area->y2 + 1;
183	        blend_area.y2 = outer_area->y2;
184	        lv_epic_draw_blend(draw_task, &blend_dsc);
185	    }
186	
187	    /*If the border is very thick and the vertical sides overlap horizontally draw a single rectangle*/
188	    if (inner_area->x1 >= inner_area->x2 && left_side && right_side)
189	    {
190	        blend_area.x1 = outer_area->x1;
191	        blend_area.x2 = outer_area->x2;
192	        blend_area.y1 = core_area.y1;
193	        blend_area.y2 = core_area.y2;
194	        lv_epic_draw_blend(draw_task, &blend_dsc);
195	    }
196	    else
197	    {
198	        if (left_side)
199	        {
200	            blend_area.x1 = outer_area->x1;
201	            blend_area.x2 = inner_area->x1 - 1;
202	            blend_area.y1 = core_area.y1;
203	            blend_area.y2 = core_area.y2;
204	            lv_epic_draw_blend(draw_task, &blend_dsc);
205	        }
206	
207	        if (right_side)
208	        {
209	            blend_area.x1 = inner_area->x2 + 1;
210	            blend_area.x2 = outer_area->x2;
211	            blend_area.y1 = core_area.y1;
212	            blend_area.y2 = core_area.y2;
213	            lv_epic_draw_blend(draw_task, &blend_dsc);
214	        }
215	    }
216	
217	    /*Draw the corners*/
218	    lv_coord_t blend_w;
219	
220	    /*Left and right corner together if they are close to each other*/
221	    if (!split_hor)
222	    {
223	        /*Calculate the top corner and mirror it to the bottom*/
224	        blend_area.x1 = draw_area.x1;
225	        blend_area.x2 = draw_area.x2;
226	        lv_coord_t max_h = LV_MAX(rout, inner_area->y1 - outer_area->y1);
227	        for (h = 0; h < max_h; h++)
228	        {
229	            lv_coord_t top_y = outer_area->y1 + h;
230	            lv_coord_t bottom_y = outer_area->y2 - h;
231	            if (top_y < draw_area.y1 && bottom_y > draw_area.y2) continue;  /*This line is clipped now*/
232	
233	            lv_memset(mask_buf, 0xff, draw_area_w);
234	            blend_dsc.mask_res = lv_draw_sw_mask_apply(mask_list, mask_buf, blend_area.x1, top_y, draw_area_w);
235	
236	            if (top_y >= draw_area.y1)
237	            {
238	                blend_area.y1 = top_y;
239	                blend_area.y2 = top_y;
240	                lv_epic_draw_blend(draw_task, &blend_dsc);
241	            }
242	
243	            if (bottom_y <= draw_area.y2)
244	            {
245	                blend_area.y1 = bottom_y;
246	                blend_area.y2 = bottom_y;
247	                lv_epic_draw_blend(draw_task, &blend_dsc);
248	            }
249	        }
250	    }
251	    else
252	    {
253	        /*Left corners*/
254	        blend_area.x1 = draw_area.x1;
255	        blend_area.x2 = LV_MIN(draw_area.x2, core_area.x1 - 1);
256	        blend_w = lv_area_get_width(&blend_area);
257	        if (blend_w > 0)
258	        {
259	            if (left_side || top_side)
260	            {
261	                for (h = draw_area.y1; h < core_area.y1; h++)
262	                {
263	                    blend_area.y1 = h;
264	                    blend_area.y2 = h;
265	
266	                    lv_memset(mask_buf, 0xff, blend_w);
267	                    blend_dsc.mask_res = lv_draw_sw_mask_apply(mask_list, mask_buf, blend_area.x1, h, blend_w);
268	                    lv_epic_draw_blend(draw_task, &blend_dsc);
269	                }
270	            }
271	
272	            if (left_side || bottom_side)
273	            {
274	                for (h = core_area.y2 + 1; h <= draw_area.y2; h++)
275	                {
276	                    blend_area.y1 = h;
277	                    blend_area.y2 = h;
278	
279	                    lv_memset(mask_buf, 0xff, blend_w);
280	                    blend_dsc.mask_res = lv_draw_sw_mask_apply(mask_list, mask_buf, blend_area.x1, h, blend_w);
281	                    lv_epic_draw_blend(draw_task, &blend_dsc);
282	                }
283	            }
284	        }
285	
286	        /*Right corners*/
287	        blend_area.x1 = LV_MAX(draw_area.x1, blend_area.x2 + 1);    /*To not overlap with the left side*/
288	        blend_area.x1 = LV_MAX(draw_area.x1, core_area.x2 + 1);
289	
290	        blend_area.x2 = draw_area.x2;
291	        blend_w = lv_area_get_width(&blend_area);
292	
293	        if (blend_w > 0)
294	        {
295	            if (right_side || top_side)
296	            {
297	                for (h = draw_area.y1; h < core_area.y1; h++)
298	                {
299	                    blend_area.y1 = h;
300	                    blend_area.y2 = h;
301	
302	                    lv_memset(mask_buf, 0xff, blend_w);
303	                    blend_dsc.mask_res = lv_draw_sw_mask_apply(mask_list, mask_buf, blend_area.x1, h, blend_w);
304	                    lv_epic_draw_blend(draw_task, &blend_dsc);
305	                }
306	            }
307	
308	            if (right_side || bottom_side)
309	            {
310	                for (h = core_area.y2 + 1; h <= draw_area.y2; h++)
311	                {
312	                    blend_area.y1 = h;
313	                    blend_area.y2 = h;
314	
315	                    lv_memset(mask_buf, 0xff, blend_w);
316	                    blend_dsc.mask_res = lv_draw_sw_mask_apply(mask_list, mask_buf, blend_area.x1, h, blend_w);
317	                    lv_epic_draw_blend(draw_task, &blend_dsc);
318	                }
319	            }
320	        }
321	    }
322	
323	    lv_draw_sw_mask_free_param(&mask_rin_param);
324	    if (rout > 0) lv_draw_sw_mask_free_param(&mask_rout_param);
325	    lv_free(mask_buf);
