329	static void draw_border_simple(lv_draw_task_t *draw_task, const lv_area_t *outer_area, const lv_area_t *inner_area,
330	                               lv_color_t color, lv_opa_t opa)
331	{
332	    lv_area_t a;
333	    lv_draw_sw_blend_dsc_t blend_dsc;
334	    lv_memzero(&blend_dsc, sizeof(lv_draw_sw_blend_dsc_t));
335	    blend_dsc.blend_area = &a;
336	    blend_dsc.color = color;
337	    blend_dsc.opa = opa;
338	
339	    bool top_side = outer_area->y1 <= inner_area->y1;
340	    bool bottom_side = outer_area->y2 >= inner_area->y2;
341	    bool left_side = outer_area->x1 <= inner_area->x1;
342	    bool right_side = outer_area->x2 >= inner_area->x2;
343	
344	    /*Top*/
345	    a.x1 = outer_area->x1;
346	    a.x2 = outer_area->x2;
347	    a.y1 = outer_area->y1;
348	    a.y2 = inner_area->y1 - 1;
349	    if (top_side)
350	    {
351	        lv_epic_draw_blend(draw_task, &blend_dsc);
352	    }
353	
354	    /*Bottom*/
355	    a.y1 = inner_area->y2 + 1;
356	    a.y2 = outer_area->y2;
357	    if (bottom_side)
358	    {
359	        lv_epic_draw_blend(draw_task, &blend_dsc);
360	    }
361	
362	    /*Left*/
363	    a.x1 = outer_area->x1;
364	    a.x2 = inner_area->x1 - 1;
365	    a.y1 = (top_side) ? inner_area->y1 : outer_area->y1;
366	    a.y2 = (bottom_side) ? inner_area->y2 : outer_area->y2;
367	    if (left_side)
368	    {
369	        lv_epic_draw_blend(draw_task, &blend_dsc);
370	    }
371	
372	    /*Right*/
373	    a.x1 = inner_area->x2 + 1;
374	    a.x2 = outer_area->x2;
375	    if (right_side)
376	    {
377	        lv_epic_draw_blend(draw_task, &blend_dsc);
378	    }
379	}
