/**
 * @file lv_epic_utils.h
 *
 * Shared helpers for the EPIC draw unit. See lv_draw_epic.h for the
 * porting notes.
 *
 * SPDX-FileCopyrightText: 2019-2022 SiFli Technologies(Nanjing) Co., Ltd
 * SPDX-License-Identifier: Apache-2.0
 */

#ifndef LV_EPIC_UTILS_H
#define LV_EPIC_UTILS_H

#ifdef __cplusplus
extern "C" {
#endif

/*********************
 *      INCLUDES
 *********************/

#include "lv_draw_epic.h"

#if LV_USE_DRAW_EPIC
#include "../sw/blend/lv_draw_sw_blend.h"

/**********************
 * GLOBAL PROTOTYPES
 **********************/

/**
 * Map an LVGL color format to an EPIC input color mode.
 * @return the EPIC color mode or UINT32_MAX if not supported
 */
uint32_t lv_img_2_epic_cf(lv_color_format_t cf);

EPIC_ColorDef lv_color_to_epic_color(lv_color_t color, lv_opa_t opa);

uint32_t lv_epic_setup_bg_and_output_layer(EPIC_LayerConfigTypeDef * epic_bg_layer,
                                           EPIC_LayerConfigTypeDef * epic_output_layer,
                                           lv_draw_unit_t * draw_unit, const lv_area_t * coords);

/**
 * Blend a color or an image, going through EPIC when every buffer is
 * GPU-reachable and falling back to lv_draw_sw_blend() otherwise.
 */
void lv_epic_draw_blend(lv_draw_unit_t * draw_unit, const lv_draw_sw_blend_dsc_t * blend_dsc);

#endif /*LV_USE_DRAW_EPIC*/

#ifdef __cplusplus
} /*extern "C"*/
#endif

#endif /*LV_EPIC_UTILS_H*/

/**
 * @file lv_epic_utils.c
 *
 * Ported from SiFli-SDK middleware/lvgl/lv_drivers_v9/sifli/lv_epic_utils.c
 * and adapted to this repository's LVGL 9.1 fork (draw-unit based API).
 * See lv_draw_epic.h for the porting notes.
 *
 * SPDX-FileCopyrightText: 2019-2022 SiFli Technologies(Nanjing) Co., Ltd
 * SPDX-License-Identifier: Apache-2.0
 */

/*********************
 *      INCLUDES
 *********************/

#include "lv_draw_epic.h"

#if LV_USE_DRAW_EPIC
#include "lv_epic_utils.h"

#include <string.h>

#include "../lv_draw.h"
#include "../sw/lv_draw_sw_mask.h"
#include "../sw/blend/lv_draw_sw_blend.h"
#include "../../misc/lv_area.h"

/*********************
 *      DEFINES
 *********************/
#define GPU_OPERATION_MAX_PIXELS (1000*1000)

/**********************
 *   GLOBAL FUNCTIONS
 **********************/

uint32_t lv_img_2_epic_cf(lv_color_format_t cf)
{
    switch(cf) {
        /*2 byte (+alpha) formats*/
        case LV_COLOR_FORMAT_RGB565:
            return EPIC_INPUT_RGB565;
#ifdef EPIC_SUPPORT_MASK
        case LV_COLOR_FORMAT_RGB565A8:
            return EPIC_INPUT_RGB565;
#endif /*EPIC_SUPPORT_MASK*/

        /*3 byte (+alpha) formats*/
        case LV_COLOR_FORMAT_RGB888:
            return EPIC_INPUT_RGB888;
        case LV_COLOR_FORMAT_ARGB8888:
        case LV_COLOR_FORMAT_XRGB8888:
            return EPIC_INPUT_ARGB8888;
        case LV_COLOR_FORMAT_ARGB8565:
            return EPIC_INPUT_ARGB8565;

#ifdef EPIC_SUPPORT_A8
        case LV_COLOR_FORMAT_A8:
            return EPIC_INPUT_A8;
#endif /*EPIC_SUPPORT_A8*/

#ifdef EPIC_SUPPORT_A4
        case LV_COLOR_FORMAT_A4:
            return EPIC_INPUT_A4;
#endif /*EPIC_SUPPORT_A4*/

#ifdef EPIC_SUPPORT_A2
        case LV_COLOR_FORMAT_A2:
            return EPIC_INPUT_A2;
#endif /*EPIC_SUPPORT_A2*/

#ifdef EPIC_SUPPORT_L8
        case LV_COLOR_FORMAT_I8:
        case LV_COLOR_FORMAT_L8:
            return EPIC_INPUT_L8;
#endif /*EPIC_SUPPORT_L8*/

#ifdef EPIC_SUPPORT_YUV
        case LV_COLOR_FORMAT_I420:
            return EPIC_INPUT_YUV420_PLANAR;
        case LV_COLOR_FORMAT_YUY2:
            return EPIC_INPUT_YUV422_PACKED_YUYV;
        case LV_COLOR_FORMAT_UYVY:
            return EPIC_INPUT_YUV422_PACKED_UYVY;
#endif /*EPIC_SUPPORT_YUV*/

        default:
            /*Unlike the SDK original this must not assert: evaluate()
             *probes formats to decide whether to take a task at all.*/
            return UINT32_MAX;
    }
}

EPIC_ColorDef lv_color_to_epic_color(lv_color_t color, lv_opa_t opa)
{
    EPIC_ColorDef c;
    c.ch.color_r = color.red;
    c.ch.color_g = color.green;
    c.ch.color_b = color.blue;
    c.ch.alpha = opa;
    return c;
}

uint32_t lv_epic_setup_bg_and_output_layer(EPIC_LayerConfigTypeDef * epic_bg_layer,
                                           EPIC_LayerConfigTypeDef * epic_output_layer,
                                           lv_draw_unit_t * draw_unit, const lv_area_t * coords)
{
    lv_layer_t * layer = draw_unit->target_layer;

    lv_area_t blend_area;
    if(!_lv_area_intersect(&blend_area, coords, draw_unit->clip_area))
        return 1; /*Fully clipped, nothing to do*/

    lv_color_format_t dest_cf = layer->color_format;

    /*Setup bg layer*/
    HAL_EPIC_LayerConfigInit(epic_bg_layer);
    epic_bg_layer->color_en = false;
    epic_bg_layer->data = (uint8_t *)lv_draw_layer_go_to_xy(layer, 0, 0);
    epic_bg_layer->color_mode = lv_img_2_epic_cf(dest_cf);
    epic_bg_layer->width = lv_area_get_width(&layer->buf_area);
    epic_bg_layer->total_width = lv_area_get_width(&layer->buf_area);
    epic_bg_layer->height = lv_area_get_height(&layer->buf_area);
    epic_bg_layer->x_offset = layer->buf_area.x1;
    epic_bg_layer->y_offset = layer->buf_area.y1;

    /*Setup output layer*/
    memcpy(epic_output_layer, epic_bg_layer, sizeof(EPIC_LayerConfigTypeDef));
    epic_output_layer->width = lv_area_get_width(&blend_area);
    epic_output_layer->height = lv_area_get_height(&blend_area);
    epic_output_layer->x_offset = blend_area.x1;
    epic_output_layer->y_offset = blend_area.y1;

    epic_output_layer->data = (uint8_t *)lv_draw_layer_go_to_xy(layer,
                                                                blend_area.x1 - layer->buf_area.x1,
                                                                blend_area.y1 - layer->buf_area.y1);

    LV_ASSERT((epic_output_layer->height * epic_output_layer->width) <= GPU_OPERATION_MAX_PIXELS);

    return 0;
}

void lv_epic_draw_blend(lv_draw_unit_t * draw_unit, const lv_draw_sw_blend_dsc_t * blend_dsc)
{
    /*Do not draw transparent things*/
    if(blend_dsc->opa <= LV_OPA_MIN) return;
    if(blend_dsc->mask_buf && blend_dsc->mask_res == LV_DRAW_SW_MASK_RES_TRANSP) return;

    lv_area_t blend_area;
    if(!_lv_area_intersect(&blend_area, blend_dsc->blend_area, draw_unit->clip_area)) return;

    lv_layer_t * layer = draw_unit->target_layer;

    /*Anything EPIC cannot reach (PSRAM) goes to the software blender.
     *This keeps corner cases (masks or sources allocated from the PSRAM
     *heap) rendering correctly instead of hanging the GPU.*/
    bool mask_used = blend_dsc->mask_buf &&
                     blend_dsc->mask_res != LV_DRAW_SW_MASK_RES_FULL_COVER;
    if(!drv_epic_addr_reachable(layer->draw_buf ? layer->draw_buf->data : NULL) ||
       (blend_dsc->src_buf && !drv_epic_addr_reachable(blend_dsc->src_buf)) ||
       (mask_used && !drv_epic_addr_reachable(blend_dsc->mask_buf)) ||
       (blend_dsc->src_buf && lv_img_2_epic_cf(blend_dsc->src_color_format) == UINT32_MAX)) {
        lv_draw_sw_blend(draw_unit, blend_dsc);
        return;
    }

    EPIC_LayerConfigTypeDef input_layers[3];
    EPIC_LayerConfigTypeDef output_canvas;

    int ret;

    if(lv_epic_setup_bg_and_output_layer(&input_layers[0], &output_canvas, draw_unit,
                                         blend_dsc->blend_area))
        return; /*Fully clipped, nothing to do*/

    if(blend_dsc->src_buf == NULL) {
        output_canvas.color_r = blend_dsc->color.red;
        output_canvas.color_g = blend_dsc->color.green;
        output_canvas.color_b = blend_dsc->color.blue;

        LV_ASSERT((output_canvas.height * output_canvas.width) <= GPU_OPERATION_MAX_PIXELS);
        output_canvas.color_en = true;

        if(mask_used) {
#if defined(EPIC_SUPPORT_MONOCHROME_LAYER)&&defined(EPIC_SUPPORT_MASK)
            HAL_EPIC_LayerConfigInit(&input_layers[1]);
            input_layers[1].data = (uint8_t *)blend_dsc->mask_buf;
            input_layers[1].x_offset = blend_dsc->mask_area->x1;
            input_layers[1].y_offset = blend_dsc->mask_area->y1;
            input_layers[1].width = lv_area_get_width(blend_dsc->mask_area);
            input_layers[1].total_width = lv_area_get_width(blend_dsc->mask_area);
            input_layers[1].height = lv_area_get_height(blend_dsc->mask_area);
            input_layers[1].color_mode = EPIC_INPUT_A8;
            input_layers[1].ax_mode = ALPHA_BLEND_RGBCOLOR;
            input_layers[1].color_r = blend_dsc->color.red;
            input_layers[1].color_g = blend_dsc->color.green;
            input_layers[1].color_b = blend_dsc->color.blue;
            input_layers[1].alpha = blend_dsc->opa;
            input_layers[1].color_en = true;

            output_canvas.color_en = false;

            ret = drv_epic_fill_ext(input_layers, 2, &output_canvas, NULL);
#else
            LV_ASSERT(0);
#endif /* EPIC_SUPPORT_MONOCHROME_LAYER&&EPIC_SUPPORT_MASK */
        }
        else if(blend_dsc->opa < LV_OPA_MAX) {
            input_layers[0].alpha = (0 == blend_dsc->opa) ? 255 : (256 - blend_dsc->opa);

            ret = drv_epic_fill_ext(input_layers, 1, &output_canvas, NULL);
        }
        else {
            ret = drv_epic_fill_ext(NULL, 0, &output_canvas, NULL);
        }

        LV_ASSERT(0 == ret);
    }
    else {
        if(!_lv_area_intersect(&blend_area, &blend_area, blend_dsc->src_area)) return;

        /*Setup fg layer*/
        HAL_EPIC_LayerConfigInit(&input_layers[1]);

        input_layers[1].alpha = blend_dsc->opa;
        input_layers[1].x_offset = blend_dsc->src_area->x1;
        input_layers[1].y_offset = blend_dsc->src_area->y1;

        input_layers[1].color_mode = lv_img_2_epic_cf(blend_dsc->src_color_format);
        input_layers[1].data = (uint8_t *)blend_dsc->src_buf;
        input_layers[1].width = lv_area_get_width(blend_dsc->src_area);
        input_layers[1].height = lv_area_get_height(blend_dsc->src_area);
        input_layers[1].total_width = blend_dsc->src_stride /
                                      lv_color_format_get_size(blend_dsc->src_color_format);

        if(mask_used) {
#if defined(EPIC_SUPPORT_MONOCHROME_LAYER)&&defined(EPIC_SUPPORT_MASK)
            HAL_EPIC_LayerConfigInit(&input_layers[2]);
            input_layers[2].data = (uint8_t *)blend_dsc->mask_buf;
            input_layers[2].x_offset = blend_dsc->mask_area->x1;
            input_layers[2].y_offset = blend_dsc->mask_area->y1;
            input_layers[2].width = lv_area_get_width(blend_dsc->mask_area);
            input_layers[2].total_width = lv_area_get_width(blend_dsc->mask_area);
            input_layers[2].height = lv_area_get_height(blend_dsc->mask_area);
            input_layers[2].color_mode = EPIC_INPUT_A8;
            input_layers[2].ax_mode = ALPHA_BLEND_MASK;

            ret = drv_epic_blend(input_layers, 3, &output_canvas, NULL);
#else
            LV_ASSERT(0);
#endif /* EPIC_SUPPORT_MONOCHROME_LAYER&&EPIC_SUPPORT_MASK */
        }
        else {
            ret = drv_epic_blend(input_layers, 2, &output_canvas, NULL);
        }

        LV_ASSERT(0 == ret);
    }
}

#endif /*LV_USE_DRAW_EPIC*/

/**
 * @file lv_draw_epic.c
 *
 * SiFli EPIC 2.5D GPU draw unit: registration, task evaluation and
 * dispatching.
 *
 * Ported from SiFli-SDK middleware/lvgl/lv_drivers_v9/sifli/lv_draw_epic.c
 * and adapted to this repository's LVGL 9.1 fork; the dispatch flow follows
 * src/draw/vg_lite/lv_draw_vg_lite.c of this tree (synchronous execution,
 * no render thread: LV_USE_OS is 0 in this firmware).
 *
 * On top of the SDK original, dispatch() re-checks at runtime that every
 * buffer the GPU would touch is EPIC-reachable (EPIC cannot access PSRAM);
 * otherwise the task is handed back to the software unit. This makes the
 * unit safe regardless of where LVGL allocated the target/layer/image
 * buffers.
 *
 * SPDX-FileCopyrightText: 2019-2022 SiFli Technologies(Nanjing) Co., Ltd
 * SPDX-License-Identifier: Apache-2.0
 */

/*********************
 *      INCLUDES
 *********************/

#include "lv_draw_epic.h"

#if LV_USE_DRAW_EPIC
#include "lv_epic_utils.h"

#include "../lv_draw.h"
#include "../lv_image_decoder.h"
#include "../../display/lv_display_private.h"
#include "../../misc/lv_area.h"

/*********************
 *      DEFINES
 *********************/

#define DRAW_UNIT_ID_EPIC 5

/*Must match DRAW_UNIT_ID_SW in ../sw/lv_draw_sw.c*/
#define DRAW_UNIT_ID_SW_FALLBACK 1

/**********************
 *      TYPEDEFS
 **********************/
typedef struct _lv_draw_epic_unit_t {
    lv_draw_unit_t base_unit;
    lv_draw_task_t * task_act;
} lv_draw_epic_unit_t;

/**********************
 *  STATIC PROTOTYPES
 **********************/

static int32_t dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer);
static int32_t evaluate(lv_draw_unit_t * draw_unit, lv_draw_task_t * task);
static int32_t draw_delete(lv_draw_unit_t * draw_unit);
static void execute_drawing(lv_draw_epic_unit_t * u);

/**********************
 *  STATIC VARIABLES
 **********************/
static uint8_t initialized = 0;

/**********************
 *   GLOBAL FUNCTIONS
 **********************/

void lv_draw_epic_init(void)
{
    if(!initialized) {
        lv_draw_epic_unit_t * draw_epic_unit = lv_draw_create_unit(sizeof(lv_draw_epic_unit_t));
        draw_epic_unit->base_unit.dispatch_cb = dispatch;
        draw_epic_unit->base_unit.evaluate_cb = evaluate;
        draw_epic_unit->base_unit.delete_cb = draw_delete;
        draw_epic_unit->base_unit.name = "EPIC";
        drv_gpu_open();

        initialized = 1;
    }
}

void lv_draw_epic_deinit(void)
{
    if(initialized) {
        drv_gpu_close();
        initialized = 0;
    }
}

/**********************
 *   STATIC FUNCTIONS
 **********************/

static inline bool cf_supported(lv_color_format_t cf)
{
    /*Normal images. Unlike the SDK original there is no EZIP/JPEG flag
     *support: this fork's decoder does not carry those formats.*/
    if(LV_COLOR_FORMAT_RGB565 == cf || LV_COLOR_FORMAT_ARGB8565 == cf ||
       LV_COLOR_FORMAT_RGB888 == cf || LV_COLOR_FORMAT_ARGB8888 == cf ||
       LV_COLOR_FORMAT_XRGB8888 == cf)
        return true;

#ifdef EPIC_SUPPORT_A8
    if(LV_COLOR_FORMAT_A8 == cf) return true;
#endif /*EPIC_SUPPORT_A8*/

#ifdef EPIC_SUPPORT_MASK
    if(LV_COLOR_FORMAT_RGB565A8 == cf) return true;
#endif

#ifdef EPIC_SUPPORT_A4
    if(LV_COLOR_FORMAT_A4 == cf) return true;
#endif /*EPIC_SUPPORT_A4*/

#ifdef EPIC_SUPPORT_A2
    if(LV_COLOR_FORMAT_A2 == cf) return true;
#endif /*EPIC_SUPPORT_A2*/

#ifdef EPIC_SUPPORT_L8
    if((LV_COLOR_FORMAT_I8 == cf) || (LV_COLOR_FORMAT_L8 == cf)) return true;
#endif /*EPIC_SUPPORT_L8*/

#ifdef EPIC_SUPPORT_YUV
    if(LV_COLOR_FORMAT_I420 == cf || LV_COLOR_FORMAT_YUY2 == cf || LV_COLOR_FORMAT_UYVY == cf)
        return true;
#endif /*EPIC_SUPPORT_YUV*/

    return false;
}

/*EPIC can only write RGB565/ARGB8565/RGB888/ARGB8888 outputs*/
static inline bool dest_cf_supported(lv_color_format_t cf)
{
    uint32_t epic_cf = lv_img_2_epic_cf(cf);

    if(epic_cf == UINT32_MAX) return false;
    return EPIC_SUPPROT_OUT_FORMAT(epic_cf) ? true : false;
}

static int32_t evaluate(lv_draw_unit_t * draw_unit, lv_draw_task_t * t)
{
    LV_UNUSED(draw_unit);

    /*The destination is always the target layer of the task*/
    if(t->target_layer && !dest_cf_supported(t->target_layer->color_format))
        return 0;

    switch(t->type) {
        case LV_DRAW_TASK_TYPE_FILL: {
                const lv_draw_fill_dsc_t * draw_dsc = (const lv_draw_fill_dsc_t *) t->draw_dsc;

                /*Rounded rectangles cannot go through EPIC*/
                if(draw_dsc->radius != 0)
                    return 0;

                /*The EPIC gradient engine handles exactly 2 stops,
                 *horizontal or vertical*/
                if(draw_dsc->grad.dir != LV_GRAD_DIR_NONE &&
                   (draw_dsc->grad.stops_count != 2 ||
                    (draw_dsc->grad.dir != LV_GRAD_DIR_VER && draw_dsc->grad.dir != LV_GRAD_DIR_HOR)))
                    return 0;

                if(t->preference_score > 70) {
                    t->preference_score = 70;
                    t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
                }
                return 1;
            }

#ifdef EPIC_SUPPORT_A8
        case LV_DRAW_TASK_TYPE_LABEL: {
                const lv_draw_label_dsc_t * label_dsc = (const lv_draw_label_dsc_t *)t->draw_dsc;

                /*Vector glyphs (FreeType outline mode) cannot go through
                 *EPIC. Probe the first character like the SDK original.*/
                if(label_dsc->font && label_dsc->text) {
                    lv_font_glyph_dsc_t glyph_dsc;
                    if(lv_font_get_glyph_dsc(label_dsc->font, &glyph_dsc,
                                             (uint32_t)label_dsc->text[0], '\0') &&
                       glyph_dsc.format == LV_FONT_GLYPH_FORMAT_VECTOR) {
                        return 0;
                    }
                }

                if(t->preference_score > 95) {
                    t->preference_score = 95;
                    t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
                }
                return 1;
            }
#endif /*EPIC_SUPPORT_A8*/

        case LV_DRAW_TASK_TYPE_BORDER: {
                const lv_draw_border_dsc_t * draw_dsc = (lv_draw_border_dsc_t *) t->draw_dsc;

                if(draw_dsc->side != (lv_border_side_t)LV_BORDER_SIDE_FULL)
                    return 0;

                if(draw_dsc->radius != 0)
                    return 0;

                if(t->preference_score > 90) {
                    t->preference_score = 90;
                    t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
                }
                return 1;
            }

        case LV_DRAW_TASK_TYPE_LAYER: {
                const lv_draw_image_dsc_t * draw_dsc = (const lv_draw_image_dsc_t *) t->draw_dsc;
                lv_layer_t * layer_to_draw = (lv_layer_t *)draw_dsc->src;

                bool has_recolor = (draw_dsc->recolor_opa != LV_OPA_TRANSP);
                bool has_transform = (draw_dsc->rotation != 0 || draw_dsc->scale_x != LV_SCALE_NONE ||
                                      draw_dsc->scale_y != LV_SCALE_NONE);

                if(has_recolor || (!cf_supported(layer_to_draw->color_format)))
                    return 0;
                if((LV_COLOR_FORMAT_RGB565A8 == layer_to_draw->color_format) && has_transform)
                    return 0;
                if(draw_dsc->skew_x != 0 || draw_dsc->skew_y != 0)
                    return 0;

                if(t->preference_score > 80) {
                    t->preference_score = 80;
                    t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
                }
                return 1;
            }

        case LV_DRAW_TASK_TYPE_IMAGE: {
                lv_draw_image_dsc_t * draw_dsc = (lv_draw_image_dsc_t *) t->draw_dsc;

                bool has_recolor = (draw_dsc->recolor_opa != LV_OPA_TRANSP);
                bool has_transform = (draw_dsc->rotation != 0 || draw_dsc->scale_x != LV_SCALE_NONE ||
                                      draw_dsc->scale_y != LV_SCALE_NONE);

                if(has_recolor || (!cf_supported(draw_dsc->header.cf)))
                    return 0;

                if((LV_COLOR_FORMAT_RGB565A8 == draw_dsc->header.cf) && has_transform)
                    return 0;
                if(draw_dsc->skew_x != 0 || draw_dsc->skew_y != 0)
                    return 0;

                /*Only variable (C array) sources are accepted: their pixel
                 *data stays in flash/SRAM where EPIC can read it. File
                 *sources are decoded into PSRAM cache buffers which EPIC
                 *cannot access.*/
                if(lv_image_src_get_type(draw_dsc->src) != LV_IMAGE_SRC_VARIABLE)
                    return 0;

                const lv_image_dsc_t * img_dsc = (const lv_image_dsc_t *)draw_dsc->src;
                if(!drv_epic_addr_reachable(img_dsc->data))
                    return 0;
                if(img_dsc->header.flags & LV_IMAGE_FLAGS_COMPRESSED)
                    return 0;

                if(t->preference_score > 80) {
                    t->preference_score = 80;
                    t->preferred_draw_unit_id = DRAW_UNIT_ID_EPIC;
                }
                return 1;
            }

        default:
            return 0;
    }

    return 0;
}

/**
 * Runtime re-check of buffers that only exist by dispatch time.
 * Returns false if the task must fall back to the software unit.
 */
static bool task_buffers_reachable(lv_draw_task_t * t, lv_layer_t * layer)
{
    if(layer->draw_buf == NULL || !drv_epic_addr_reachable(layer->draw_buf->data))
        return false;

    if(t->type == LV_DRAW_TASK_TYPE_LAYER) {
        const lv_draw_image_dsc_t * draw_dsc = (const lv_draw_image_dsc_t *) t->draw_dsc;
        lv_layer_t * layer_to_draw = (lv_layer_t *)draw_dsc->src;

        /*NULL draw_buf is fine: lv_draw_epic_layer() returns early on it*/
        if(layer_to_draw->draw_buf != NULL &&
           !drv_epic_addr_reachable(layer_to_draw->draw_buf->data))
            return false;
    }

    return true;
}

static int32_t dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer)
{
    lv_draw_epic_unit_t * draw_epic_unit = (lv_draw_epic_unit_t *) draw_unit;

    /*Return immediately if it's busy with a draw task*/
    if(draw_epic_unit->task_act) {
        return 0;
    }

    /*Try to get a task ready to draw*/
    lv_draw_task_t * t = lv_draw_get_next_available_task(layer, NULL, DRAW_UNIT_ID_EPIC);
    if(t == NULL) {
        return -1;
    }

    void * buf = lv_draw_layer_alloc_buf(layer);
    if(buf == NULL) {
        return -1;
    }

    /*EPIC cannot access PSRAM. If any involved buffer ended up there,
     *hand the task back to the software unit.*/
    if(!task_buffers_reachable(t, layer)) {
        t->preferred_draw_unit_id = DRAW_UNIT_ID_SW_FALLBACK;
        lv_draw_dispatch_request();
        return 0;
    }

    t->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
    draw_epic_unit->base_unit.target_layer = layer;
    draw_epic_unit->base_unit.clip_area = &t->clip_area;
    draw_epic_unit->task_act = t;

    execute_drawing(draw_epic_unit);

    draw_epic_unit->task_act->state = LV_DRAW_TASK_STATE_READY;
    draw_epic_unit->task_act = NULL;

    /*The draw unit is free now. Request a new dispatching as it can get a new task*/
    lv_draw_dispatch_request();

    return 1;
}

static int32_t draw_delete(lv_draw_unit_t * draw_unit)
{
    LV_UNUSED(draw_unit);
    lv_draw_epic_deinit();
    return 1;
}

static void execute_drawing(lv_draw_epic_unit_t * u)
{
    lv_draw_task_t * t = u->task_act;
    lv_draw_unit_t * draw_unit = (lv_draw_unit_t *)u;

    int ret = drv_epic_wait_done();
    if(ret != 0) {
        LV_LOG_ERROR("epic wait_done error %d", ret);
    }

    switch(t->type) {
        case LV_DRAW_TASK_TYPE_FILL:
            lv_draw_epic_fill(draw_unit, t->draw_dsc, &t->area);
            break;
        case LV_DRAW_TASK_TYPE_BORDER:
            lv_draw_epic_border(draw_unit, t->draw_dsc, &t->area);
            break;
        case LV_DRAW_TASK_TYPE_LABEL:
            lv_draw_epic_label(draw_unit, t->draw_dsc, &t->area);
            break;
        case LV_DRAW_TASK_TYPE_IMAGE:
            lv_draw_epic_img(draw_unit, t->draw_dsc, &t->area);
            break;
        case LV_DRAW_TASK_TYPE_LAYER:
            lv_draw_epic_layer(draw_unit, t->draw_dsc, &t->area);
            break;
        default:
            break;
    }

    /*The unit runs synchronously: everything is finished before the task
     *is marked ready, so the flushed buffer is always consistent.*/
    drv_epic_wait_done();
}

#endif /*LV_USE_DRAW_EPIC*/

