/**
 * @file lv_draw_epic_label.c
 *
 * Ported from SiFli-SDK middleware/lvgl/lv_drivers_v9/sifli/
 * lv_draw_epic_label.c and adapted to this repository's LVGL 9.1 fork:
 * here lv_draw_label_iterate_characters() prefetches the glyph bitmap into
 * glyph_dsc->glyph_data (an A8 lv_draw_buf_t) before invoking the
 * callback, so the callback does not fetch bitmaps itself like the newer
 * SDK original does.
 *
 * Glyphs are blended in the EPIC "continuous blend" session: the first
 * glyph configures the pipeline, subsequent glyphs only swap the A8
 * source, which amortizes the per-operation setup cost across the whole
 * label. Unreachable buffers fall back to the software blender per glyph.
 *
 * SPDX-FileCopyrightText: 2019-2022 SiFli Technologies(Nanjing) Co., Ltd
 * SPDX-License-Identifier: Apache-2.0
 */

/*********************
 *      INCLUDES
 *********************/

#include "lv_draw_epic.h"

#if LV_USE_DRAW_EPIC
#include "lv_epic_utils.h"

#include "../lv_draw.h"
#include "../lv_draw_label.h"
#include "../sw/blend/lv_draw_sw_blend.h"
#include "../../misc/lv_area.h"
#include "../../stdlib/lv_string.h"

/**********************
 *  STATIC PROTOTYPES
 **********************/

static void draw_epic_letter_cb(lv_draw_unit_t * draw_unit, lv_draw_glyph_dsc_t * glyph_draw_dsc,
                                lv_draw_fill_dsc_t * fill_draw_dsc, const lv_area_t * fill_area);

/**********************
 *   GLOBAL FUNCTIONS
 **********************/

void lv_draw_epic_label(lv_draw_unit_t * draw_unit, const lv_draw_label_dsc_t * dsc,
                        const lv_area_t * coords)
{
    if(dsc->opa <= LV_OPA_MIN) return;

    lv_draw_label_iterate_characters(draw_unit, dsc, coords, draw_epic_letter_cb);

    drv_epic_cont_blend_reset();
}

/**********************
 *   STATIC FUNCTIONS
 **********************/

static void draw_epic_letter_cb(lv_draw_unit_t * draw_unit, lv_draw_glyph_dsc_t * glyph_draw_dsc,
                                lv_draw_fill_dsc_t * fill_draw_dsc, const lv_area_t * fill_area)
{
    if(glyph_draw_dsc) {
        switch(glyph_draw_dsc->format) {
            case LV_FONT_GLYPH_FORMAT_NONE: {
#if LV_USE_FONT_PLACEHOLDER
                    /* Draw a placeholder rectangle*/
                    lv_draw_border_dsc_t border_draw_dsc;
                    lv_draw_border_dsc_init(&border_draw_dsc);
                    border_draw_dsc.opa = glyph_draw_dsc->opa;
                    border_draw_dsc.color = glyph_draw_dsc->color;
                    border_draw_dsc.width = 1;
                    lv_draw_epic_border(draw_unit, &border_draw_dsc, glyph_draw_dsc->bg_coords);
#endif
                }
                break;
            case LV_FONT_GLYPH_FORMAT_A1:
            case LV_FONT_GLYPH_FORMAT_A2:
            case LV_FONT_GLYPH_FORMAT_A4:
            case LV_FONT_GLYPH_FORMAT_A8:
            case LV_FONT_GLYPH_FORMAT_IMAGE: {
                    if(glyph_draw_dsc->rotation % 3600 == 0 &&
                       glyph_draw_dsc->format != LV_FONT_GLYPH_FORMAT_IMAGE) {
                        /*Do not draw transparent things*/
                        if(glyph_draw_dsc->opa <= LV_OPA_MIN)
                            break;

                        const lv_draw_buf_t * draw_buf = glyph_draw_dsc->glyph_data;
                        if(draw_buf == NULL || glyph_draw_dsc->letter_coords == NULL)
                            break;

                        uint32_t glyph_width = lv_area_get_width(glyph_draw_dsc->letter_coords);
                        uint32_t glyph_height = lv_area_get_height(glyph_draw_dsc->letter_coords);
                        if(glyph_width == 0 || glyph_height == 0)
                            break;

                        lv_layer_t * layer = draw_unit->target_layer;

                        /*The glyph draw buf comes from the font draw buf
                         *handlers; it may live in PSRAM where EPIC cannot
                         *read. Blend such glyphs in software instead.*/
                        if(!drv_epic_addr_reachable(draw_buf->data) ||
                           layer->draw_buf == NULL ||
                           !drv_epic_addr_reachable(layer->draw_buf->data)) {
                            lv_area_t mask_area = *glyph_draw_dsc->letter_coords;
                            mask_area.x2 = mask_area.x1 +
                                           lv_draw_buf_width_to_stride(glyph_width, LV_COLOR_FORMAT_A8) - 1;
                            lv_draw_sw_blend_dsc_t blend_dsc;
                            lv_memzero(&blend_dsc, sizeof(blend_dsc));
                            blend_dsc.color = glyph_draw_dsc->color;
                            blend_dsc.opa = glyph_draw_dsc->opa;
                            blend_dsc.mask_buf = draw_buf->data;
                            blend_dsc.mask_area = &mask_area;
                            blend_dsc.mask_stride = draw_buf->header.stride;
                            blend_dsc.blend_area = glyph_draw_dsc->letter_coords;
                            blend_dsc.mask_res = LV_DRAW_SW_MASK_RES_CHANGED;
                            lv_draw_sw_blend(draw_unit, &blend_dsc);
                            break;
                        }

                        EPIC_LayerConfigTypeDef input_layers[2];
                        EPIC_LayerConfigTypeDef output_canvas;

                        if(lv_epic_setup_bg_and_output_layer(&input_layers[0], &output_canvas,
                                                             draw_unit,
                                                             glyph_draw_dsc->letter_coords)) {
                            break; /*Fully clipped, nothing to do*/
                        }

                        HAL_EPIC_LayerConfigInit(&input_layers[1]);
                        input_layers[1].alpha = glyph_draw_dsc->opa;
                        input_layers[1].x_offset = glyph_draw_dsc->letter_coords->x1;
                        input_layers[1].y_offset = glyph_draw_dsc->letter_coords->y1;
                        input_layers[1].data = (uint8_t *)draw_buf->data;
                        input_layers[1].data_size = draw_buf->data_size;
                        input_layers[1].color_en = true;
                        input_layers[1].color_r = glyph_draw_dsc->color.red;
                        input_layers[1].color_g = glyph_draw_dsc->color.green;
                        input_layers[1].color_b = glyph_draw_dsc->color.blue;
                        input_layers[1].ax_mode = ALPHA_BLEND_RGBCOLOR;
                        input_layers[1].width = glyph_width;
                        input_layers[1].height = glyph_height;
                        input_layers[1].color_mode = EPIC_INPUT_A8;
                        input_layers[1].total_width = draw_buf->header.stride;

                        int ret = drv_epic_cont_blend(input_layers, 2, &output_canvas);
                        LV_ASSERT(0 == ret);
                        LV_UNUSED(ret);
                    }
                    else {
                        lv_draw_image_dsc_t img_dsc;
                        lv_draw_image_dsc_init(&img_dsc);
                        img_dsc.rotation = glyph_draw_dsc->rotation;
                        img_dsc.scale_x = LV_SCALE_NONE;
                        img_dsc.scale_y = LV_SCALE_NONE;
                        img_dsc.opa = glyph_draw_dsc->opa;
                        img_dsc.src = glyph_draw_dsc->glyph_data;
                        img_dsc.recolor = glyph_draw_dsc->color;
                        img_dsc.pivot = (lv_point_t) {
                            .x = glyph_draw_dsc->pivot.x,
                            .y = glyph_draw_dsc->g->box_h + glyph_draw_dsc->g->ofs_y
                        };
                        /*Rotated glyphs and image glyphs keep the software
                         *path: recolor is required here and EPIC does not
                         *support recolor.*/
                        lv_draw_sw_image(draw_unit, &img_dsc, glyph_draw_dsc->letter_coords);
                    }
                    break;
                }
            default:
                break;
        }
    }

    if(fill_draw_dsc && fill_area) {
        lv_draw_epic_fill(draw_unit, fill_draw_dsc, fill_area);
    }
}

