/**
 * @file lv_draw_epic_img.c
 *
 * Ported from SiFli-SDK middleware/lvgl/lv_drivers_v9/sifli/
 * lv_draw_epic_img.c and adapted to this repository's LVGL 9.1 fork.
 * See lv_draw_epic.h for the porting notes.
 *
 * Differences from the SDK original:
 *   - no EZIP/JPEG compressed sources (this fork's decoder has no such
 *     flags); evaluate() only accepts plain variable image sources
 *   - bitmap_mask_src images are rejected in evaluate(), so the mask
 *     layer setup was dropped here
 *
 * IMAGE/LAYER tasks with rotation or scaling are the core of this unit:
 * the transform runs on the EPIC hardware (this is where the official
 * SiFli watch faces get their smooth scaling/rotation from).
 *
 * SPDX-FileCopyrightText: 2019-2022 SiFli Technologies(Nanjing) Co., Ltd
 * SPDX-License-Identifier: Apache-2.0
 */

/*********************
 *      INCLUDES
 *********************/

#include "lv_draw_epic.h"

#if LV_USE_DRAW_EPIC
#include "lv_epic_utils.h"

#include "../lv_draw.h"
#include "../lv_draw_image.h"
#include "../lv_image_decoder.h"
#include "../sw/blend/lv_draw_sw_blend.h"
#include "../../misc/lv_area.h"
#include "../../misc/lv_log.h"

/**********************
 *  STATIC PROTOTYPES
 **********************/

static void img_draw_core(lv_draw_unit_t * draw_unit, const lv_draw_image_dsc_t * draw_dsc,
                          const lv_image_decoder_dsc_t * decoder_dsc, lv_draw_image_sup_t * sup,
                          const lv_area_t * img_coords, const lv_area_t * clipped_img_area);

/**********************
 *   GLOBAL FUNCTIONS
 **********************/

void lv_draw_epic_layer(lv_draw_unit_t * draw_unit, const lv_draw_image_dsc_t * draw_dsc,
                        const lv_area_t * coords)
{
    lv_layer_t * layer_to_draw = (lv_layer_t *)draw_dsc->src;

    /*It can happen that nothing was drawn on a layer and therefore its
     *buffer is not allocated. In this case just return.*/
    if(layer_to_draw->draw_buf == NULL) return;

    lv_draw_image_dsc_t new_draw_dsc = *draw_dsc;
    new_draw_dsc.src = layer_to_draw->draw_buf;
    lv_draw_epic_img(draw_unit, &new_draw_dsc, coords);
}

void lv_draw_epic_img(lv_draw_unit_t * draw_unit, const lv_draw_image_dsc_t * draw_dsc,
                      const lv_area_t * coords)
{
    if(!draw_dsc->tile) {
        _lv_draw_image_normal_helper(draw_unit, draw_dsc, coords, img_draw_core);
    }
    else {
        _lv_draw_image_tiled_helper(draw_unit, draw_dsc, coords, img_draw_core);
    }
}

/**********************
 *   STATIC FUNCTIONS
 **********************/

static void img_draw_core(lv_draw_unit_t * draw_unit, const lv_draw_image_dsc_t * draw_dsc,
                          const lv_image_decoder_dsc_t * decoder_dsc, lv_draw_image_sup_t * sup,
                          const lv_area_t * img_coords, const lv_area_t * clipped_img_area)
{
    LV_UNUSED(sup);

    const lv_draw_buf_t * decoded = decoder_dsc->decoded;
    const uint8_t * src_buf = decoded->data;
    lv_color_format_t cf = decoded->header.cf;
    uint32_t img_total_width = decoded->header.stride / lv_color_format_get_size(cf);

    if(src_buf == NULL) return;

    lv_layer_t * layer = draw_unit->target_layer;
    bool has_transform = (draw_dsc->rotation != 0 || draw_dsc->scale_x != LV_SCALE_NONE ||
                          draw_dsc->scale_y != LV_SCALE_NONE);

    /*The decoder may have produced a buffer EPIC cannot reach (PSRAM).
     *evaluate()/dispatch() filter the common cases; this is the last
     *line of defense.*/
    if(!drv_epic_addr_reachable(src_buf) ||
       layer->draw_buf == NULL || !drv_epic_addr_reachable(layer->draw_buf->data) ||
       lv_img_2_epic_cf(cf) == UINT32_MAX) {
        if(!has_transform && !(cf == LV_COLOR_FORMAT_A8)) {
            /*Simple blit: the software blender handles it directly*/
            lv_draw_sw_blend_dsc_t blend_dsc;
            lv_memzero(&blend_dsc, sizeof(blend_dsc));
            blend_dsc.opa = draw_dsc->opa;
            blend_dsc.src_buf = src_buf;
            blend_dsc.src_area = img_coords;
            blend_dsc.src_stride = decoded->header.stride;
            blend_dsc.src_color_format = cf;
            blend_dsc.blend_area = clipped_img_area;
            lv_draw_sw_blend(draw_unit, &blend_dsc);
        }
        else {
            LV_LOG_WARN("EPIC: unreachable transformed image dropped");
        }
        return;
    }

    EPIC_LayerConfigTypeDef input_layers[3];
    EPIC_LayerConfigTypeDef output_canvas;

    uint8_t input_layer_cnt = 2;

    if(lv_epic_setup_bg_and_output_layer(&input_layers[0], &output_canvas, draw_unit,
                                         clipped_img_area))
        return; /*Fully clipped, nothing to do*/

    /*Setup fg layer*/
    HAL_EPIC_LayerConfigInit(&input_layers[1]);

    input_layers[1].transform_cfg.angle   = (draw_dsc->rotation + 3600) % 3600;
    input_layers[1].transform_cfg.pivot_x = draw_dsc->pivot.x;
    input_layers[1].transform_cfg.pivot_y = draw_dsc->pivot.y;
    input_layers[1].transform_cfg.scale_x =
        LV_SCALE_NONE * EPIC_INPUT_SCALE_NONE / (uint32_t)draw_dsc->scale_x;
    input_layers[1].transform_cfg.scale_y =
        LV_SCALE_NONE * EPIC_INPUT_SCALE_NONE / (uint32_t)draw_dsc->scale_y;

    input_layers[1].alpha = draw_dsc->opa;
    input_layers[1].x_offset = img_coords->x1;
    input_layers[1].y_offset = img_coords->y1;

    input_layers[1].color_mode = lv_img_2_epic_cf(cf);

    input_layers[1].data = (uint8_t *)src_buf;
    input_layers[1].data_size = decoded->data_size;

    input_layers[1].width = lv_area_get_width(img_coords);
    input_layers[1].height = lv_area_get_height(img_coords);
    input_layers[1].total_width = img_total_width;

    if(EPIC_INPUT_A8 == input_layers[1].color_mode) {
        input_layers[1].color_en = true;
        input_layers[1].color_r = draw_dsc->recolor.red;
        input_layers[1].color_g = draw_dsc->recolor.green;
        input_layers[1].color_b = draw_dsc->recolor.blue;
    }
#ifdef EPIC_SUPPORT_L8
    else if(EPIC_INPUT_L8 == input_layers[1].color_mode) {
        input_layers[1].lookup_table = (uint8_t *)decoder_dsc->palette;
    }
#endif
    else {
        input_layers[1].color_en = false;
    }

    if(LV_COLOR_FORMAT_RGB565A8 == cf) {
        /*Setup alpha layer*/
        HAL_EPIC_LayerConfigInit(&input_layers[input_layer_cnt]);

        input_layers[input_layer_cnt].alpha = draw_dsc->opa;
        input_layers[input_layer_cnt].x_offset = img_coords->x1;
        input_layers[input_layer_cnt].y_offset = img_coords->y1;
        input_layers[input_layer_cnt].color_mode = EPIC_INPUT_A8;
        input_layers[input_layer_cnt].data =
            ((uint8_t *)src_buf) + lv_area_get_size(img_coords) * 2;
        input_layers[input_layer_cnt].ax_mode = ALPHA_BLEND_OVERWRITE;
        input_layers[input_layer_cnt].width = lv_area_get_width(img_coords);
        input_layers[input_layer_cnt].height = lv_area_get_height(img_coords);
        input_layers[input_layer_cnt].total_width = img_total_width;
        input_layer_cnt++;
    }

    int ret = drv_epic_blend(input_layers, input_layer_cnt, &output_canvas, NULL);
    LV_ASSERT(0 == ret);
    LV_UNUSED(ret);
}

